        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[2] * 0.25 * S2 * inv_S1 * inv_S1 * inv_S4 * inv_S4 * a_i * (

                        -(QC_0*delta[d0][d1] + QD_0*delta[c0][d1] + QD_1*delta[c0][d0])*(delta[a0][b0]*(delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + delta[a0][b1]*(delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]) + delta[a0][g0]*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1]) + delta[a0][g1]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0]) + delta[g0][g1]*(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0]))

                        -2*delta[b0][b1]*(delta[a0][g0]*delta[a1][g1] + delta[a0][g1]*delta[a1][g0])*(QC_0*delta[d0][d1] + QD_0*delta[c0][d1] + QD_1*delta[c0][d0])

                    )

                    + F9_t[2] * 0.5 * inv_S1 * inv_S4 * inv_S4 * a_i * a_i * (

                        +(-PA_0*PA_1*PA_x + PA_0*PA_1*PQ[g0] + PA_0*PA_x*PQ[a1] + PA_1*PA_x*PQ[a0])*(delta[b0][b1]*delta[c0][d0]*delta[d1][g1] + delta[b0][b1]*delta[c0][d1]*delta[d0][g1] + delta[b0][b1]*delta[c0][g1]*delta[d0][d1] + delta[b0][c0]*delta[b1][g1]*delta[d0][d1] + delta[b0][d0]*delta[b1][g1]*delta[c0][d1] + delta[b0][d1]*delta[b1][g1]*delta[c0][d0] + delta[b0][g1]*delta[b1][c0]*delta[d0][d1] + delta[b0][g1]*delta[b1][d0]*delta[c0][d1] + delta[b0][g1]*delta[b1][d1]*delta[c0][d0]) + (-PA_0*PA_1*PA_y + PA_0*PA_1*PQ[g1] + PA_0*PA_y*PQ[a1] + PA_1*PA_y*PQ[a0])*(delta[b0][b1]*delta[c0][d0]*delta[d1][g0] + delta[b0][b1]*delta[c0][d1]*delta[d0][g0] + delta[b0][b1]*delta[c0][g0]*delta[d0][d1] + delta[b0][c0]*delta[b1][g0]*delta[d0][d1] + delta[b0][d0]*delta[b1][g0]*delta[c0][d1] + delta[b0][d1]*delta[b1][g0]*delta[c0][d0] + delta[b0][g0]*delta[b1][c0]*delta[d0][d1] + delta[b0][g0]*delta[b1][d0]*delta[c0][d1] + delta[b0][g0]*delta[b1][d1]*delta[c0][d0]) + (-PA_0*PA_1*PB_0 + PA_0*PA_1*PQ[b0] + PA_0*PB_0*PQ[a1] + PA_1*PB_0*PQ[a0])*(delta[b1][c0]*delta[d0][d1]*delta[g0][g1] + delta[b1][d0]*delta[c0][d1]*delta[g0][g1] + delta[b1][d1]*delta[c0][d0]*delta[g0][g1] + delta[b1][g0]*delta[c0][d0]*delta[d1][g1] + delta[b1][g0]*delta[c0][d1]*delta[d0][g1] + delta[b1][g0]*delta[c0][g1]*delta[d0][d1] + delta[b1][g1]*delta[c0][d0]*delta[d1][g0] + delta[b1][g1]*delta[c0][d1]*delta[d0][g0] + delta[b1][g1]*delta[c0][g0]*delta[d0][d1]) + (-PA_0*PA_1*PB_1 + PA_0*PA_1*PQ[b1] + PA_0*PB_1*PQ[a1] + PA_1*PB_1*PQ[a0])*(delta[b0][c0]*delta[d0][d1]*delta[g0][g1] + delta[b0][d0]*delta[c0][d1]*delta[g0][g1] + delta[b0][d1]*delta[c0][d0]*delta[g0][g1] + delta[b0][g0]*delta[c0][d0]*delta[d1][g1] + delta[b0][g0]*delta[c0][d1]*delta[d0][g1] + delta[b0][g0]*delta[c0][g1]*delta[d0][d1] + delta[b0][g1]*delta[c0][d0]*delta[d1][g0] + delta[b0][g1]*delta[c0][d1]*delta[d0][g0] + delta[b0][g1]*delta[c0][g0]*delta[d0][d1]) + (-PA_0*PA_x*PA_y + PA_0*PA_x*PQ[g1] + PA_0*PA_y*PQ[g0] + PA_x*PA_y*PQ[a0])*(delta[a1][b0]*delta[b1][c0]*delta[d0][d1] + delta[a1][b0]*delta[b1][d0]*delta[c0][d1] + delta[a1][b0]*delta[b1][d1]*delta[c0][d0] + delta[a1][b1]*delta[b0][c0]*delta[d0][d1] + delta[a1][b1]*delta[b0][d0]*delta[c0][d1] + delta[a1][b1]*delta[b0][d1]*delta[c0][d0] + delta[a1][c0]*delta[b0][b1]*delta[d0][d1] + delta[a1][d0]*delta[b0][b1]*delta[c0][d1] + delta[a1][d1]*delta[b0][b1]*delta[c0][d0]) + (-PA_0*PA_x*PB_0 + PA_0*PA_x*PQ[b0] + PA_0*PB_0*PQ[g0] + PA_x*PB_0*PQ[a0])*(delta[a1][b1]*delta[c0][d0]*delta[d1][g1] + delta[a1][b1]*delta[c0][d1]*delta[d0][g1] + delta[a1][b1]*delta[c0][g1]*delta[d0][d1] + delta[a1][c0]*delta[b1][g1]*delta[d0][d1] + delta[a1][d0]*delta[b1][g1]*delta[c0][d1] + delta[a1][d1]*delta[b1][g1]*delta[c0][d0] + delta[a1][g1]*delta[b1][c0]*delta[d0][d1] + delta[a1][g1]*delta[b1][d0]*delta[c0][d1] + delta[a1][g1]*delta[b1][d1]*delta[c0][d0]) + (-PA_0*PA_x*PB_1 + PA_0*PA_x*PQ[b1] + PA_0*PB_1*PQ[g0] + PA_x*PB_1*PQ[a0])*(delta[a1][b0]*delta[c0][d0]*delta[d1][g1] + delta[a1][b0]*delta[c0][d1]*delta[d0][g1] + delta[a1][b0]*delta[c0][g1]*delta[d0][d1] + delta[a1][c0]*delta[b0][g1]*delta[d0][d1] + delta[a1][d0]*delta[b0][g1]*delta[c0][d1] + delta[a1][d1]*delta[b0][g1]*delta[c0][d0] + delta[a1][g1]*delta[b0][c0]*delta[d0][d1] + delta[a1][g1]*delta[b0][d0]*delta[c0][d1] + delta[a1][g1]*delta[b0][d1]*delta[c0][d0]) + (-PA_0*PA_y*PB_0 + PA_0*PA_y*PQ[b0] + PA_0*PB_0*PQ[g1] + PA_y*PB_0*PQ[a0])*(delta[a1][b1]*delta[c0][d0]*delta[d1][g0] + delta[a1][b1]*delta[c0][d1]*delta[d0][g0] + delta[a1][b1]*delta[c0][g0]*delta[d0][d1] + delta[a1][c0]*delta[b1][g0]*delta[d0][d1] + delta[a1][d0]*delta[b1][g0]*delta[c0][d1] + delta[a1][d1]*delta[b1][g0]*delta[c0][d0] + delta[a1][g0]*delta[b1][c0]*delta[d0][d1] + delta[a1][g0]*delta[b1][d0]*delta[c0][d1] + delta[a1][g0]*delta[b1][d1]*delta[c0][d0]) + (-PA_0*PA_y*PB_1 + PA_0*PA_y*PQ[b1] + PA_0*PB_1*PQ[g1] + PA_y*PB_1*PQ[a0])*(delta[a1][b0]*delta[c0][d0]*delta[d1][g0] + delta[a1][b0]*delta[c0][d1]*delta[d0][g0] + delta[a1][b0]*delta[c0][g0]