                    + F9_t[3] * 0.5 * S2 * inv_S1 * inv_S4 * inv_S4 * inv_S4 * a_i * a_i * (

                        +(-PA_0*PA_1*PQ[b0] - PA_0*PB_0*PQ[a1] + PA_0*PQ[a1]*PQ[b0] - PA_1*PB_0*PQ[a0] + PA_1*PQ[a0]*PQ[b0] + PB_0*PQ[a0]*PQ[a1])*(delta[b1][c0]*delta[d0][d1]*delta[g0][g1] + delta[b1][d0]*delta[c0][d1]*delta[g0][g1] + delta[b1][d1]*delta[c0][d0]*delta[g0][g1] + delta[b1][g0]*delta[c0][d0]*delta[d1][g1] + delta[b1][g0]*delta[c0][d1]*delta[d0][g1] + delta[b1][g0]*delta[c0][g1]*delta[d0][d1] + delta[b1][g1]*delta[c0][d0]*delta[d1][g0] + delta[b1][g1]*delta[c0][d1]*delta[d0][g0] + delta[b1][g1]*delta[c0][g0]*delta[d0][d1]) + (-PA_0*PA_1*PQ[b1] - PA_0*PB_1*PQ[a1] + PA_0*PQ[a1]*PQ[b1] - PA_1*PB_1*PQ[a0] + PA_1*PQ[a0]*PQ[b1] + PB_1*PQ[a0]*PQ[a1])*(delta[b0][c0]*delta[d0][d1]*delta[g0][g1] + delta[b0][d0]*delta[c0][d1]*delta[g0][g1] + delta[b0][d1]*delta[c0][d0]*delta[g0][g1] + delta[b0][g0]*delta[c0][d0]*delta[d1][g1] + delta[b0][g0]*delta[c0][d1]*delta[d0][g1] + delta[b0][g0]*delta[c0][g1]*delta[d0][d1] + delta[b0][g1]*delta[c0][d0]*delta[d1][g0] + delta[b0][g1]*delta[c0][d1]*delta[d0][g0] + delta[b0][g1]*delta[c0][g0]*delta[d0][d1]) + (-PA_0*PA_1*PQ[g0] - PA_0*PA_x*PQ[a1] + PA_0*PQ[a1]*PQ[g0] - PA_1*PA_x*PQ[a0] + PA_1*PQ[a0]*PQ[g0] + PA_x*PQ[a0]*PQ[a1])*(delta[b0][b1]*delta[c0][d0]*delta[d1][g1] + delta[b0][b1]*delta[c0][d1]*delta[d0][g1] + delta[b0][b1]*delta[c0][g1]*delta[d0][d1] + delta[b0][c0]*delta[b1][g1]*delta[d0][d1] + delta[b0][d0]*delta[b1][g1]*delta[c0][d1] + delta[b0][d1]*delta[b1][g1]*delta[c0][d0] + delta[b0][g1]*delta[b1][c0]*delta[d0][d1] + delta[b0][g1]*delta[b1][d0]*delta[c0][d1] + delta[b0][g1]*delta[b1][d1]*delta[c0][d0]) + (-PA_0*PA_1*PQ[g1] - PA_0*PA_y*PQ[a1] + PA_0*PQ[a1]*PQ[g1] - PA_1*PA_y*PQ[a0] + PA_1*PQ[a0]*PQ[g1] + PA_y*PQ[a0]*PQ[a1])*(delta[b0][b1]*delta[c0][d0]*delta[d1][g0] + delta[b0][b1]*delta[c0][d1]*delta[d0][g0] + delta[b0][b1]*delta[c0][g0]*delta[d0][d1] + delta[b0][c0]*delta[b1][g0]*delta[d0][d1] + delta[b0][d0]*delta[b1][g0]*delta[c0][d1] + delta[b0][d1]*delta[b1][g0]*delta[c0][d0] + delta[b0][g0]*delta[b1][c0]*delt