                        -3*(PQ[c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + PQ[d0]*PQ[d1]*QC_0)*(delta[a0][a1]*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + delta[a0][b0]*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + delta[a0][b1]*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]) + delta[a0][g0]*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) + delta[a0][g1]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]))

