        const auto c0 = k % 3;
        const auto d0 = d_cart_inds[l % 6][0];
        const auto d1 = d_cart_inds[l % 6][1];

        // J. Chem. Phys. 84, 3963-3974 (1986)

        const auto S2 = a_k + a_l;

        const auto inv_S2 = 1.0 / S2;
        const auto inv_S4 = 1.0 / (S1 + S2);

        const double PQ[3] = {(a_k * r_k[0] + a_l * r_l[0]) * inv_S2 - (a_i * r_i[0] + a_j * r_j[0]) * inv_S1,
                              (a_k * r_k[1] + a_l * r_l[1]) * inv_S2 - (a_i * r_i[1] + a_j * r_j[1]) * inv_S1,
                              (a_k * r_k[2] + a_l * r_l[2]) * inv_S2 - (a_i * r_i[2] + a_j * r_j[2]) * inv_S1};

        const auto r2_PQ = PQ[0] * PQ[0] + PQ[1] * PQ[1] + PQ[2] * PQ[2];

        const auto Lambda = sqrt(4.0 * S1 * S2 * MATH_CONST_INV_PI * inv_S4);

        double F9_t[4];

        gpu::computeBoysFunction(F9_t, S1 * S2 * inv_S4 * r2_PQ, 3, boys_func_table, boys_func_ft);

        const auto QC_0 = (a_l * inv_S2) * (r_l[c0] - r_k[c0]);
        const auto QD_0 = (-a_k * inv_S2) * (r_l[d0] - r_k[d0]);
        const auto QD_1 = (-a_k * inv_S2) * (r_l[d1] - r_k[d1]);

        double kl_factor = 2.0;

        // mu-mu hessian

        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[3] * 2.0 * S2 * S2 * S2 * inv_S1 * inv_S4 * inv_S4 * inv_S4 * a_i * a_i * (

                        +QC_0*QD_0*QD_1*(-PA_1*PQ[g1]*(PB_1*(PQ[b0]*delta[a0][g0] + PQ[g0]*delta[a0][b0]) + PQ[b1]*(PA_x*delta[a0][b0] + PB_0*delta[a0][g0])) + PQ[a0]*(PA_1*PQ[b0]*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) - PA_1*(PA_x*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1] + PQ[g1]*delta[b0][b1]) + PA_y*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) + PB_0*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) + PB_1*(PQ[b0]*delta[g0][g1] + PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0])) + PA_x*PQ[a1]*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1] + PQ[g1]*delta[b0][b1]) + PA_x*PQ[b0]*(PQ[b1]*delta[a1][g1] + PQ[g1]*delta[a1][b1]) - PA_x*(PA_y*(PQ[a1]*delta[b0][b1] + PQ[b0]*delta[a1][b1] + PQ[b1]*delta[a1][b0]) + PB_0*(PQ[a1]*delta[b1][g1] + PQ[b1]*delta[a1][g1] + PQ[g1]*delta[a1][b1]) + PB_1*(PQ[a1]*delta[b0][g1] + PQ[b0]*delta[a1][g1] + PQ[g1]*delta[a1][b0])) + PA_y*PQ[a1]*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) - PA_y*(PB_0*(PQ[a1]*delta[b1][g0] + PQ[b1]*delta[a1][g0] + PQ[g0]*delta[a1][b1]) + PB_1*(PQ[a1]*delta[b0][g0] + PQ[b0]*delta[a1][g0] + PQ[g0]*delta[a1][b0])) - PB_0*PB_1*(PQ[a1]*delta[g0][g1] + PQ[g0]*delta[a1][g1] + PQ[g1]*delta[a1][g0]) + PB_0*PQ[a1]*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) + PB_1*PQ[a1]*(PQ[b0]*delta[g0][g1] + PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0]) + PQ[b1]*PQ[g0]*(PA_y*delta[a1][b0] + PB_0*delta[a1][g1]) + PQ[g0]*PQ[g1]*(PA_1*delta[b0][b1] + PB_0*delta[a1][b1] + PB_1*delta[a1][b0])) + PQ[a1]*(PA_0*(-PA_x*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1] + PQ[g1]*delta[b0][b1]) - PA_y*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) - PB_0*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) - PB_1*(PQ[b0]*delta[g0][g1] + PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0]) + PQ[b1]*PQ[g1]*delta[b0][g0]) + PA_x*(-PA_y + PQ[g1])*(PQ[b0]*delta[a0][b1] + PQ[b1]*delta[a0][b0]) + PA_y*(-PB_1 + PQ[b1])*(PQ[b0]*delta[a0][g0] + PQ[g0]*delta[a0][b0]) + PB_1*(-PB_0 + PQ[b0])*(PQ[g0]*delta[a0][g1] + PQ[g1]*delta[a0][g0]) + (-PA_x + PQ[g0])*(PB_0*(PQ[b1]*delta[a0][g1] + PQ[g1]*delta[a0][b1]) + PB_1*PQ[g1]*delta[a0][b0])) + PQ[b0]*(PA_0*(-PA_1 + PQ[a1])*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) - PA_x*(PQ[b1]*(PA_0*delta[a1][g1] + PA_1*delta[a0][g1] + PA_y*delta[a0][a1]) + PQ[g1]*(PA_0*delta[a1][b1] + PA_1*delta[a0][b1] + PB_1*delta[a0][a1])) + delta[a0][g1]*(-PB_1 + PQ[b1])*(PA_1*PQ[g0] + PA_x*PQ[a1]) + delta[a1][g0]*(PB_1*PQ[g1]*(-PA_0 + PQ[a0]) + PQ[b1]*(PA_0*(-PA_y + PQ[g1]) + PA_y*PQ[a0]))) + PQ[b1]*(PQ[g1]*(-PA_0 + PQ[a0])*(PA_1*delta[b0][g0] + PA_x*delta[a1][b0] + PB_0*delta[a1][g0]) + delta[a0][a1]*(-PB_0 + PQ[b0])*(PA_x*PQ[g1] + PA_y*PQ[g0]) + delta[a0][g0]*(-PA_y + PQ[g1])*(PA_1*PQ[b0] + PB_0*PQ[a1])) + PQ[g0]*(PA_0*(PQ[b1]*(-PA_1*delta[b0][g1] - PA_y*delta[a1][b0] - PB_0*delta[a1][g1] + PQ[a1]*delta[b0][g1]) + PQ[g1]*(-PA_1*delta[b0][b1] - PB_0*delta[a1][b1] - PB_1*delta[a1][b0] + PQ[a1]*delta[b0][b1] + PQ[b0]*delta[a1][b1] + PQ[b1]*delta[a1][b0])) + PA_1*PQ[b1]*(-PB_0*delta[a0][g1] + PQ[a0]*delta[b0][g1] + delta[a0][b0]*(-PA_y + PQ[g1])) + PQ[b0]*(PA_y*(-PA_0*delta[a1][b1] - PA_1*delta[a0][b1] - PB_1*delta[a0][a1] + PQ[a0]*delta[a1][b1]) + delta[a1][g1]*(PA_0*(-PB_1 + PQ[b1]) + PB_1*PQ[a0])) + PQ[g1]*delta[a0][a1]*(PB_0*(-PB_1 + PQ[b1]) + PB_1*PQ[b0]) + delta[a0][b1]*(-PB_0 + PQ[b0])*(PA_1*PQ[g1] + PA_y*PQ[a1])))

                    )

                    + F9_t[3] * S2 * S2 * S2 * inv_S1 * inv_S4 * inv_S4 * inv_S4 * a_i * (

                        +QC_0*QD_0*QD_1*(PQ[b0]*PQ[b1]*delta[a0][a1]*delta[g0][g1] + delta[b0][b1]*(PQ[a0]*(PQ[a1]*delta[g0][g1] + PQ[g0]*delta[a1][g1] + PQ[g1]*delta[a1][g0]) + PQ[a1]*(PQ[g0]*delta[a0][g1] + PQ[g1]*delta[a0][g0])))

                        +QC_0*QD_0*QD_1*(PQ[a0]*(PQ[b0]*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + PQ[b1]*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0])) + PQ[a1]*(PQ[b0]*(delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) + PQ[b1]*(delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0])))

                        +2.0*PQ[b0]*PQ[b1]*QC_0*QD_0*QD_1*(delta[a0][g0]*delta[a1][g1] + delta[a0][g1]*delta[a1][g0])

                        +QC_0*QD_0*QD_1*(PQ[b0]*(PQ[g0]*(delta[a0][b1]*delta[a1][g1] + delta[a0][g1]*delta[a1][b1]) + PQ[g1]*(delta[a0][b1]*delta[a1][g0] + delta[a0][g0]*delta[a1][b1])) + PQ[b1]*(PQ[g0]*(delta[a0][b0]*delta[a1][g1] + delta[a0][g1]*delta[a1][b0]) + PQ[g1]*(delta[a0][b0]*delta[a1][g0] + delta[a0][g0]*delta[a1][b0])))

                    )


                );

        ERIs[threadIdx.y] += eri_ijkl * pd_mat_D[kl] * kl_factor;
    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < dd_prim_pair_count_local))
    {
        double hess_ii_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM_LARGE; n++)
        {
            hess_ii_xy += ERIs[n];
        }

        atomicAdd(hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + i], hess_ii_xy * ij_factor_D * 2.0 * prefac_coulomb);
    }
}

