][g1] + delta[a0][g0]*delta[a1][d1]*delta[b0][g1] + delta[a0][g1]*delta[a1][b0]*delta[d1][g0] + delta[a0][g1]*delta[a1][d1]*delta[b0][g0]) + (-PQ[b1]*PQ[c0]*QD_1 - PQ[b1]*PQ[d1]*QC_0)*(delta[a0][a1]*delta[b0][d0]*delta[g0][g1] + delta[a0][b0]*delta[a1][d0]*delta[g0][g1] + delta[a0][b0]*delta[a1][g0]*delta[d0][g1] + delta[a0][b0]*delta[a1][g1]*delta[d0][g0] + delta[a0][d0]*delta[a1][b0]*delta[g0][g1] + delta[a0][d0]*delta[a1][g0]*delta[b0][g1] + delta[a0][d0]*delta[a1][g1]*delta[b0][g0] + delta[a0][g0]*delta[a1][b0]*delta[d0][g1] + delta[a0][g0]*delta[a1][d0]*delta[b0][g1] + delta[a0][g1]*delta[a1][b0]*delta[d0][g0] + delta[a0][g1]*delta[a1][d0]*delta[b0][g0]) + (-PQ[b1]*PQ[d0]*QD_1 - PQ[b1]*PQ[d1]*QD_0)*(delta[a0][a1]*delta[b0][c0]*delta[g0][g1] + delta[a0][b0]*delta[a1][c0]*delta[g0][g1] + delta[a0][b0]*delta[a1][g0]*delta[c0][g1] + delta[a0][b0]*delta[a1][g1]*delta[c0][g0] + delta[a0][c0]*delta[a1][b0]*delta[g0][g1] + delta[a0][c0]*delta[a1][g0]*delta[b0][g1] + delta[a0][c0]*delta[a1][g1]*delta[b0][g0] + delta[a0][g0]*delta[a1][b0]*delta[c0][g1] + delta[a0][g0]*delta[a1][c0]*delta[b0][g1] + delta[a0][g1]*delta[a1][b0]*delta[c0][g0] + delta[a0][g1]*delta[a1][c0]*delta[b0][g0])

                        -2*(PQ[b0]*(PQ[c0]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0]) + PQ[d0]*(QC_0*delta[b1][d1] + QD_1*delta[b1][c0]) + PQ[d1]*(QC_0*delta[b1][d0] + QD_0*delta[b1][c0])) + PQ[b1]*(PQ[c0]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0]) + PQ[d0]*(QC_0*delta[b0][d1] + QD_1*delta[b0][c0]) + PQ[d1]*(QC_0*delta[b0][d0] + QD_0*delta[b0][c0])))*(delta[a0][g0]*delta[a1][g1] + delta[a0][g1]*delta[a1][g0])

