        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[0] * (-1.0) * inv_S2 * a_j * (

                        +PA_0*PA_1*(PB_0*(PB_1*delta[g0][g1] + PB_x*delta[b1][g1] + PB_y*delta[b1][g0]) + PB_1*(PB_x*delta[b0][g1] + PB_y*delta[b0][g0]))*(QC_0*delta[d0][d1] + QD_0*delta[c0][d1] + QD_1*delta[c0][d0])

