                        +PA_0*PA_1*(PQ[c0]*(delta[b0][d0]*(delta[b1][d1]*delta[g0][g1] + delta[b1][g0]*delta[d1][g1] + delta[b1][g1]*delta[d1][g0]) + delta[b0][d1]*(delta[b1][d0]*delta[g0][g1] + delta[b1][g0]*delta[d0][g1] + delta[b1][g1]*delta[d0][g0]) + delta[b0][g0]*(delta[b1][d0]*delta[d1][g1] + delta[b1][d1]*delta[d0][g1]) + delta[b0][g1]*(delta[b1][d0]*delta[d1][g0] + delta[b1][d1]*delta[d0][g0])) + PQ[d0]*(delta[b0][c0]*(delta[b1][d1]*delta[g0][g1] + delta[b1][g0]*delta[d1][g1] + delta[b1][g1]*delta[d1][g0]) + delta[b0][d1]*(delta[b1][c0]*delta[g0][g1] + delta[b1][g0]*delta[c0][g1] + delta[b1][g1]*delta[c0][g0]) + delta[b0][g0]*(delta[b1][c0]*delta[d1][g1] + delta[b1][d1]*delta[c0][g1]) + delta[b0][g1]*(delta[b1][c0]*delta[d1][g0] + delta[b1][d1]*delta[c0][g0])) + PQ[d1]*(delta[b0][c0]*(delta[b1][d0]*delta[g0][g1] + delta[b1][g0]*delta[d0][g1] + delta[b1][g1]*delta[d0][g0]) + delta[b0][d0]*(delta[b1][c0]*delta[g0][g1] + delta[b1][g0]*delta[c0][g1] + delta[b1][g1]*delta[c0][g0]) + delta[b0][g0]*(delta[b1][c0]*delta[d0][g1] + delta[b1][d0]*delta[c0][g1]) + delta[b0][g1]*(delta[b1][c0]*delta[d0][g0] + delta[b1][d0]*delta[c0][g0])))

                        +PQ[c0]*PQ[d0]*PQ[d1]*(delta[a0][b0]*(delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + delta[a0][b1]*(delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]) + delta[a0][g0]*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1]) + delta[a0][g1]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0]) + delta[g0][g1]*(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0]))

                        +2.0*PQ[c0]*PQ[d0]*PQ[d1]*delta[a0][a1]*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])

                    )

                    + F9_t[3] * (-0.25) * S1 * inv_S4 * inv_S4 * inv_S4 * (

                        +(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])*(PQ[a0]*(delta[a1][c0]*delta[d0][d1] + delta[a1][d0]*delta[c0][d1] + delta[a1][d1]*delta[c0][d0]) + PQ[a1]*(delta[a0][c0]*delta[d0][d1] + delta[a0][d0]*delta[c0][d1] + delta[a0][d1]*delta[c0][d0]) + PQ[c0]*(delta[a0][a1]*delta[d0][d1] + delta[a0][d0]*delta[a1][d1] + delta[a0][d1]*delta[a1][d0]) + PQ[d0]*(delta[a0][a1]*delta[c0][d1] + delta[a0][c0]*delta[a1][d1] + delta[a0][d1]*delta[a1][c0]) + PQ[d1]*(delta[a0][a1]*delta[c0][d0] + delta[a0][c0]*delta[a1][d0] + delta[a0][d0]*delta[a1][c0]))

