        const auto S2 = a_k + a_l;

        const auto inv_S2 = 1.0 / S2;
        const auto inv_S4 = 1.0 / (S1 + S2);

        const double PQ[3] = {(a_k * r_k[0] + a_l * r_l[0]) * inv_S2 - (a_i * r_i[0] + a_j * r_j[0]) * inv_S1,
                              (a_k * r_k[1] + a_l * r_l[1]) * inv_S2 - (a_i * r_i[1] + a_j * r_j[1]) * inv_S1,
                              (a_k * r_k[2] + a_l * r_l[2]) * inv_S2 - (a_i * r_i[2] + a_j * r_j[2]) * inv_S1};

        const auto r2_PQ = PQ[0] * PQ[0] + PQ[1] * PQ[1] + PQ[2] * PQ[2];

        const auto Lambda = sqrt(4.0 * S1 * S2 * MATH_CONST_INV_PI * inv_S4);

        double F9_t[4];

        gpu::computeBoysFunction(F9_t, S1 * S2 * inv_S4 * r2_PQ, 3, boys_func_table, boys_func_ft);

        const auto QC_0 = (a_l * inv_S2) * (r_l[c0] - r_k[c0]);
        const auto QD_0 = (-a_k * inv_S2) * (r_l[d0] - r_k[d0]);
        const auto QD_1 = (-a_k * inv_S2) * (r_l[d1] - r_k[d1]);

        double kl_factor = 2.0;

        // nu-nu hessian

        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[3] * 2.0 * S1 * S1 * inv_S4 * inv_S4 * inv_S4 * a_j * a_j * (

                        +PA_0*PA_1*(PB_0*PB_1*(PQ[c0]*(PB_x*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1]) + PB_y*(PQ[d0]*delta[d1][g0] + PQ[d1]*delta[d0][g0])) + PQ[d0]*PQ[d1]*(PB_x*delta[c0][g1] + PB_y*delta[c0][g0])) + PB_x*PB_y*(PQ[c0]*(PB_0*(PQ[d0]*delta[b1][d1] + PQ[d1]*delta[b1][d0]) + PB_1*(PQ[d0]*delta[b0][d1] + PQ[d1]*delta[b0][d0])) + PQ[d0]*PQ[d1]*(PB_0*delta[b1][c0] + PB_1*delta[b0][c0]))) + PB_0*PB_1*PB_x*PB_y*(PQ[c0]*(PA_0*(PQ[d0]*delta[a1][d1] + PQ[d1]*delta[a1][d0]) + PA_1*(PQ[d0]*delta[a0][d1] + PQ[d1]*delta[a0][d0])) + PQ[d0]*PQ[d1]*(PA_0*delta[a1][c0] + PA_1*delta[a0][c0]))

                        +(PA_0*PA_1*(PB_0*PB_1*(PB_x*PQ[g1] + PB_y*PQ[g0]) + PB_x*PB_y*(PB_0*PQ[b1] + PB_1*PQ[b0])) + PB_0*PB_1*PB_x*PB_y*(PA_0*PQ[a1] + PA_1*PQ[a0]))*(PQ[c0]*delta[d0][d1] + PQ[d0]*delta[c0][d1] + PQ[d1]*delta[c0][d0])

                        -PQ[c0]*PQ[d0]*PQ[d1]*(PA_0*(PA_1*(PB_0*(PB_1*delta[g0][g1] + PB_x*delta[b1][g1] + PB_y*delta[b1][g0]) + PB_x*PB_y*delta[b0][b1]) + PB_1*(PB_0*PB_y*delta[a1][g0] + PB_x*(PA_1*delta[b0][g1] + PB_0*delta[a1][g1] + PB_y*delta[a1][b0]))) + PA_1*PB_1*(PB_0*PB_x*delta[a0][g1] + PB_y*(PA_0*delta[b0][g0] + PB_0*delta[a0][g0] + PB_x*delta[a0][b0])) + PB_0*PB_x*PB_y*(PA_0*delta[a1][b1] + PA_1*delta[a0][b1] + PB_1*delta[a0][a1]))

                    )

                    + F9_t[3] * S1 * S1 * inv_S4 * inv_S4 * inv_S4 * a_j * (

                        -(PA_0*(PA_1*(PB_0*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) + PB_1*(PQ[b0]*delta[g0][g1] + PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0]) + PB_x*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1]) + PB_y*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0])) + PQ[a1]*(PB_0*(PB_1*delta[g0][g1] + PB_x*delta[b1][g1] + PB_y*delta[b1][g0]) + PB_1*(PB_x*delta[b0][g1] + PB_y*delta[b0][g0]))) + PA_1*PQ[a0]*(PB_0*(PB_1*delta[g0][g1] + PB_x*delta[b1][g1] + PB_y*delta[b1][g0]) + PB_1*(PB_x*delta[b0][g1] + PB_y*delta[b0][g0])))*(PQ[c0]*delta[d0][d1] + PQ[d0]*delta[c0][d1] + PQ[d1]*delta[c0][d0])

