                        -PA_0*PA_1*(PQ[c0]*(PB_x*(PQ[d0]*(delta[b0][d1]*delta[b1][g1] + delta[b0][g1]*delta[b1][d1]) + PQ[d1]*(delta[b0][d0]*delta[b1][g1] + delta[b0][g1]*delta[b1][d0])) + PB_y*(PQ[d0]*(delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1]) + PQ[d1]*(delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0]))) + PQ[d0]*PQ[d1]*(PB_x*(delta[b0][c0]*delta[b1][g1] + delta[b0][g1]*delta[b1][c0]) + PB_y*(delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0])))

                        -(PB_0*(PB_1*delta[g0][g1] + PB_x*delta[b1][g1] + PB_y*delta[b1][g0]) + PB_1*(PB_x*delta[b0][g1] + PB_y*delta[b0][g0]))*(PQ[c0]*(PA_0*(PQ[d0]*delta[a1][d1] + PQ[d1]*delta[a1][d0]) + PA_1*(PQ[d0]*delta[a0][d1] + PQ[d1]*delta[a0][d0])) + PQ[d0]*PQ[d1]*(PA_0*delta[a1][c0] + PA_1*delta[a0][c0]))

                        +PQ[c0]*PQ[d0]*PQ[d1]*(PA_0*(PB_0*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + PB_1*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0])) + PA_1*(PB_0*(delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) + PB_1*(delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0])))

                        +PQ[c0]*PQ[d0]*PQ[d1]*(PA_0*(PB_x*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1]) + PB_y*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0])) + PA_1*(PB_x*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1]) + PB_y*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0])))

                        +PQ[c0]*PQ[d0]*PQ[d1]*(PA_0*PA_1*delta[b0][b1]*delta[g0][g1] + delta[a0][a1]*(PB_0*(PB_1*delta[g0][g1] + PB_x*delta[b1][g1] + PB_y*delta[b1][g0]) + PB_1*(PB_x*delta[b0][g1] + PB_y*delta[b0][g0])))

                        +2.0*PA_0*PA_1*PQ[c0]*PQ[d0]*PQ[d1]*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])

                    )

                    + F9_t[3] * 0.5 * S1 * S1 * inv_S4 * inv_S4 * inv_S4 * (

                        -PQ[c0]*PQ[d0]*PQ[d1]*delta[a0][a1]*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])

                        +(PA_0*PQ[a1] + PA_1*PQ[a0])*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])*(PQ[c0]*delta[d0][d1] + PQ[d0]*delta[c0][d1] + PQ[d1]*delta[c0][d0])

                        +(PQ[c0]*(PA_0*(PQ[d0]*delta[a1][d1] + PQ[d1]*delta[a1][d0]) + PA_1*(PQ[d0]*delta[a0][d1] + PQ[d1]*delta[a0][d0])) + PQ[d0]*PQ[d1]*(PA_0*delta[a1][c0] + PA_1*delta[a0][c0]))*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])

                    )


                );

        ERIs[threadIdx.y] += eri_ijkl * pd_mat_D[kl] * kl_factor;
    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < dd_prim_pair_count_local))
    {
        double hess_jj_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM_LARGE; n++)
        {
            hess_jj_xy += ERIs[n];
        }

        atomicAdd(hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + j], hess_jj_xy * ij_factor_D * 2.0 * prefac_coulomb);
    }
}

