                        +QC_0*QD_0*QD_1*(PQ[a0]*(PA_1*PQ[b0]*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) - PA_1*(PB_0*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) + PB_1*(PQ[b0]*delta[g0][g1] + PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0]) + PB_x*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1] + PQ[g1]*delta[b0][b1]) + PB_y*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1])) + PB_0*PQ[a1]*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) - PB_0*(PB_1*(PQ[a1]*delta[g0][g1] + PQ[g0]*delta[a1][g1] + PQ[g1]*delta[a1][g0]) + PB_x*(PQ[a1]*delta[b1][g1] + PQ[b1]*delta[a1][g1] + PQ[g1]*delta[a1][b1]) + PB_y*(PQ[a1]*delta[b1][g0] + PQ[b1]*delta[a1][g0] + PQ[g0]*delta[a1][b1])) + PB_1*PQ[a1]*(PQ[b0]*delta[g0][g1] + PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0]) + PB_1*PQ[b0]*(PQ[g0]*delta[a1][g1] + PQ[g1]*delta[a1][g0]) - PB_1*(PB_x*(PQ[a1]*delta[b0][g1] + PQ[b0]*delta[a1][g1] + PQ[g1]*delta[a1][b0]) + PB_y*(PQ[a1]*delta[b0][g0] + PQ[b0]*delta[a1][g0] + PQ[g0]*delta[a1][b0])) - PB_x*PB_y*(PQ[a1]*delta[b0][b1] + PQ[b0]*delta[a1][b1] + PQ[b1]*delta[a1][b0]) + PB_x*PQ[a1]*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1] + PQ[g1]*delta[b0][b1]) + PB_y*PQ[a1]*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) + PB_y*PQ[g0]*(PQ[b0]*delta[a1][b1] + PQ[b1]*delta[a1][b0])) + PQ[a1]*(PA_0*PQ[g1]*(PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) - PA_0*(PB_0*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) + PB_1*(PQ[b0]*delta[g0][g1] + PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0]) + PB_x*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1] + PQ[g1]*delta[b0][b1]) + PB_y*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1])) + PB_0*PQ[b1]*(delta[a0][g0]*(-PB_y + PQ[g1]) + delta[a0][g1]*(-PB_x + PQ[g0])) + PB_1*PQ[b0]*(delta[a0][g0]*(-PB_y + PQ[g1]) + delta[a0][g1]*(-PB_x + PQ[g0])) - PB_1*(PB_0*(PQ[g0]*delta[a0][g1] + PQ[g1]*delta[a0][g0]) + PB_x*PQ[g1]*delta[a0][b0]) + PB