                        +QC_0*QD_0*QD_1*(PQ[a0]*PQ[a1]*delta[b0][b1]*delta[g0][g1] + delta[a0][a1]*(PQ[b0]*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) + PQ[b1]*(PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0])))

