                        +(PA_1*PQ[a0]*(PQ[b0]*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) + PQ[b1]*(PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0])) + PQ[a1]*(PA_0*(PQ[b0]*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) + PQ[b1]*(PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0])) + PQ[a0]*(PB_0*(PQ[b1]*delta[g0][g1] + PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0]) + PB_1*(PQ[b0]*delta[g0][g1] + PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0]) + PB_x*(PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1]) + PB_y*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0]))))*(PQ[d0]*QC_0*QD_1 + QD_0*(PQ[c0]*QD_1 + PQ[d1]*QC_0))

