[g1]*(PQ[d0]*delta[b1][d1] + PQ[d1]*delta[b1][d0])) + PB_y*(PQ[b1]*(PQ[d0]*delta[d1][g0] + PQ[d1]*delta[d0][g0]) + PQ[g0]*(PQ[d0]*delta[b1][d1] + PQ[d1]*delta[b1][d0]))) + PB_y*(PB_1*(PQ[b0]*(PQ[d0]*delta[d1][g0] + PQ[d1]*delta[d0][g0]) + PQ[g0]*(PQ[d0]*delta[b0][d1] + PQ[d1]*delta[b0][d0])) + PB_x*(PQ[b0]*(PQ[d0]*delta[b1][d1] + PQ[d1]*delta[b1][d0]) + PQ[b1]*(PQ[d0]*delta[b0][d1] + PQ[d1]*delta[b0][d0])))) + PB_0*PB_y*(PB_1*(PQ[a1]*(PQ[d0]*delta[d1][g0] + PQ[d1]*delta[d0][g0]) + PQ[g0]*(PQ[d0]*delta[a1][d1] + PQ[d1]*delta[a1][d0])) + PB_x*(PQ[a1]*(PQ[d0]*delta[b1][d1] + PQ[d1]*delta[b1][d0]) + PQ[b1]*(PQ[d0]*delta[a1][d1] + PQ[d1]*delta[a1][d0]))) + PB_1*PB_x*(PA_1*(PQ[b0]*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1]) + PQ[g1]*(PQ[d0]*delta[b0][d1] + PQ[d1]*delta[b0][d0])) + PB_0*(PQ[a1]*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1]) + PQ[g1]*(PQ[d0]*delta[a1][d1] + PQ[d1]*delta[a1][d0])) + PB_y*(PQ[a1]*(PQ[d0]*delta[b0][d1] + PQ[d1]*delta[b0][d0]) + PQ[b0]*(PQ[d0]*delta[a1][d1] + PQ[d1]*delta[a1][d0])))) + (PA_0*(PQ[d0]*delta[a1][d1] + PQ[d1]*delta[a1][d0]) + PA_1*(PQ[d0]*delta[a0][d1] + PQ[d1]*delta[a0][d0]))*(PB_0*PQ[g0]*(PB_1*PQ[g1] + PB_y*PQ[b1]) + PB_1*PQ[b0]*(PB_x*PQ[g1] + PB_y*PQ[g0]) + PB_x*PQ[b1]*(PB_0*PQ[g1] + PB_y*PQ[b0]))) + PQ[d0]*PQ[d1]*(PA_0*(PA_1*(PQ[b0]*(PB_1*(PQ[g0]*delta[c0][g1] + PQ[g1]*delta[c0][g0]) + PB_x*(PQ[b1]*delta[c0][g1] + PQ[g1]*delta[b1][c0]) + PB_y*(PQ[b1]*delta[c0][g0] + PQ[g0]*delta[b1][c0])) + PQ[b1]*(PB_0*(PQ[g0]*delta[c0][g1] + PQ[g1]*delta[c0][g0]) + delta[b0][c0]*(PB_x*PQ[g1] + PB_y*PQ[g0])) + PQ[g0]*PQ[g1]*(PB_0*delta[b1][c0] + PB_1*delta[b0][c0])) + PQ[a1]*(PB_0*(PB_1*(PQ[g0]*delta[c0][g1] + PQ[g1]*delta[c0][g0]) + PB_x*(PQ[b1]*delta[c0][g1] + PQ[g1]*delta[b1][c0]) + PB_y*(PQ[b1]*delta[c0][g0] + PQ[g0]*delta[b1][c0])) + PB_1*(PB_x*(PQ[b0]*delta[c0][g1] + PQ[g1]*delta[b0][c0]) + PB_y*(PQ[b0]*delta[c0][g0] + PQ[g0]*delta[b0][c0])))) + PQ[a0]*(PA_1*(PB_0*(PB_1*(PQ[g0]*delta[c0][g1] + PQ[g1]*delta[c0][g0]) + PB_x*(PQ[b1]*delta[c0][g1] + PQ[g1]*delta[b1][c0]) + PB_y*(PQ[b1]*delta[c0][g0] + PQ[g0]*delta[b1][c0])) + PB_y*(PB_1*(PQ[b0]*delta[c0][g0] + PQ[g0]*delta[b0][c0]) + PB_x*(PQ[b0]*delta[b1][c0] + PQ[b1]*delta[b0][c0]))) + PB_0*PB_y*(PB_1*(PQ[a1]*delta[c0][g0] + PQ[g0]*delta[a1][c0]) + PB_x*(PQ[a1]*delta[b1][c0] + PQ[b1]*delta[a1][c0])) + PB_1*PB_x*(PA_1*(PQ[b0]*delta[c0][g1] + PQ[g1]*delta[b0][c0]) + PB_0*(PQ[a1]*delta[c0][g1] + PQ[g1]*delta[a1][c0]) + PB_y*(PQ[a1]*delta[b0][c0] + PQ[b0]*delta[a1][c0]))) + (PA_0*delta[a1][c0] + PA_1*delta[a0][c0])*(PB_0*PQ[g0]*(PB_1*PQ[g1] + PB_y*PQ[b1]) + PB_1*PQ[b0]*(PB_x*PQ[g1] + PB_y*PQ[g0]) + PB_x*PQ[b1]*(PB_0*PQ[g1] + PB_y*PQ[b0])))

                        +(PQ[c0]*delta[d0][d1] + PQ[d0]*delta[c0][d1] + PQ[d1]*delta[c0][d0])*(PA_0*PA_1*PQ[b0]*PQ[g1]*(PB_1*PQ[g0] + PB_x*PQ[b1]) + PB_0*PQ[g0]*(PA_0*PQ[a1] + PA_1*PQ[a0])*(PB_1*PQ[g1] + PB_y*PQ[b1]) + PB_1*(PB_x*PQ[g1] + PB_y*PQ[g0])*(PA_1*PQ[a0]*PQ[b0] + PQ[a1]*(PA_0*PQ[b0] + PB_0*PQ[a0])) + PB_x*PB_y*PQ[a0]*PQ[a1]*(PB_0*PQ[b1] + PB_1*PQ[b0]) + PQ[b1]*(PA_0*(PA_1*PQ[g0] + PB_x*PQ[a1]) + PA_1*PB_x*PQ[a0])*(PB_0*PQ[g1] + PB_y*PQ[b0]))

