*PQ[c0]*PQ[d0] - PA_1*PQ[a0]*PQ[b0]*PQ[c0]*PQ[d0] - PB_0*PQ[a0]*PQ[a1]*PQ[c0]*PQ[d0] + PQ[a0]*PQ[a1]*PQ[b0]*PQ[c0]*PQ[d0])

                        +(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0])*(-PB_x*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1] - PB_y*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0] + 2.0*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0]*PQ[g1]) + (delta[a0][a1]*delta[b0][g0] + delta[a0][b0]*delta[a1][g0] + delta[a0][g0]*delta[a1][b0])*(-PB_1*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1] - PB_y*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]) + (delta[a0][a1]*delta[b0][g1] + delta[a0][b0]*delta[a1][g1] + delta[a0][g1]*delta[a1][b0])*(-PB_1*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0] - PB_x*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0]) + (delta[a0][a1]*delta[b1][g0] + delta[a0][b1]*delta[a1][g0] + delta[a0][g0]*delta[a1][b1])*(-PB_0*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1] - PB_y*PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]) + (delta[a0][a1]*delta[b1][g1] + delta[a0][b1]*delta[a1][g1] + delta[a0][g1]*delta[a1][b1])*(-PB_0*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0] - PB_x*PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0]) + (delta[a0][a1]*delta[g0][g1] + delta[a0][g0]*delta[a1][g1] + delta[a0][g1]*delta[a1][g0])*(-PB_0*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1] - PB_1*PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[b0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]) + (delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])*(-PA_1*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1] - PB_y*PQ[a1]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[a1]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]) + (delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1])*(-PA_1*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0] - PB_x*PQ[a1]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[a1]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0]) + (delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0])*(-PA_1*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1] - PB_1*PQ[a1]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[a1]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]) + (delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0])*(-PA_1*PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1] - PB_0*PQ[a1]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[a1]*PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1]) + (delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1])*(-PA_0*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1] - PB_y*PQ[a0]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[a0]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]) + (delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1])*(-PA_0*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0] - PB_x*PQ[a0]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[a0]*PQ[c0]*PQ[d0]*PQ[d1]*PQ[g0]) + (delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0])*(-PA_0*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1] - PB_1*PQ[a0]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[a0]*PQ[b1]*PQ[c0]*PQ[d0]*PQ[d1]) + (delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0])*(-PA_0*PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1] - PB_0*PQ[a0]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[a0]*PQ[b0]*PQ[c0]*PQ[d0]*PQ[d1]) + (delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])*(-PA_0*PQ[a1]*PQ[c0]*PQ[d0]*PQ[d1] - PA_1*PQ[a0]*PQ[c0]*PQ[d0]*PQ[d1] + 2.0*PQ[a0]*PQ[a1]*PQ[c0]*PQ[d0]*PQ[d1])

