                        +(QC_0*delta[d0][d1] + QD_0*delta[c0][d1] + QD_1*delta[c0][d0])*(PA_0*PA_1*PQ[g0]*PQ[g1]*(PB_0*PQ[b1] + PB_1*PQ[b0]) + PA_x*PQ[b1]*(PA_0*PQ[a1] + PA_1*PQ[a0])*(PB_0*PQ[g1] + PB_y*PQ[b0]) + PB_0*(PB_1*PQ[g1] + PB_y*PQ[b1])*(PA_1*PQ[a0]*PQ[g0] + PQ[a1]*(PA_0*PQ[g0] + PA_x*PQ[a0])) + PB_1*PB_y*PQ[a0]*PQ[a1]*(PA_x*PQ[b0] + PB_0*PQ[g0]) + PQ[b0]*(PA_0*(PA_1*PQ[b1] + PB_1*PQ[a1]) + PA_1*PB_1*PQ[a0])*(PA_x*PQ[g1] + PB_y*PQ[g0]))

