]*delta[d0][g0] + delta[b0][g0]*delta[d0][d1]) + delta[a0][d0]*(delta[b0][c0]*delta[d1][g0] + delta[b0][d1]*delta[c0][g0] + delta[b0][g0]*delta[c0][d1]) + delta[a0][d1]*(delta[b0][c0]*delta[d0][g0] + delta[b0][d0]*delta[c0][g0] + delta[b0][g0]*delta[c0][d0]) + delta[a0][g0]*(delta[b0][c0]*delta[d0][d1] + delta[b0][d0]*delta[c0][d1] + delta[b0][d1]*delta[c0][d0])) + PQ[c0]*(delta[a0][a1]*(delta[b0][d0]*delta[d1][g0] + delta[b0][d1]*delta[d0][g0] + delta[b0][g0]*delta[d0][d1]) + delta[a0][b0]*(delta[a1][d0]*delta[d1][g0] + delta[a1][d1]*delta[d0][g0] + delta[a1][g0]*delta[d0][d1]) + delta[a0][d0]*(delta[a1][b0]*delta[d1][g0] + delta[a1][d1]*delta[b0][g0] + delta[a1][g0]*delta[b0][d1]) + delta[a0][d1]*(delta[a1][b0]*delta[d0][g0] + delta[a1][d0]*delta[b0][g0] + delta[a1][g0]*delta[b0][d0]) + delta[a0][g0]*(delta[a1][b0]*delta[d0][d1] + delta[a1][d0]*delta[b0][d1] + delta[a1][d1]*delta[b0][d0])) + PQ[d0]*(delta[a0][a1]*(delta[b0][c0]*delta[d1][g0] + delta[b0][d1]*delta[c0][g0] + delta[b0][g0]*delta[c0][d1]) + delta[a0][b0]*(delta[a1][c0]*delta[d1][g0] + delta[a1][d1]*delta[c0][g0] + delta[a1][g0]*delta[c0][d1]) + delta[a0][c0]*(delta[a1][b0]*delta[d1][g0] + delta[a1][d1]*delta[b0][g0] + delta[a1][g0]*delta[b0][d1]) + delta[a0][d1]*(delta[a1][b0]*delta[c0][g0] + delta[a1][c0]*delta[b0][g0] + delta[a1][g0]*delta[b0][c0]) + delta[a0][g0]*(delta[a1][b0]*delta[c0][d1] + delta[a1][c0]*delta[b0][d1] + delta[a1][d1]*delta[b0][c0])) + PQ[d1]*(delta[a0][a1]*(delta[b0][c0]*delta[d0][g0] + delta[b0][d0]*delta[c0][g0] + delta[b0][g0]*delta[c0][d0]) + delta[a0][b0]*(delta[a1][c0]*delta[d0][g0] + delta[a1][d0]*delta[c0][g0] + delta[a1][g0]*delta[c0][d0]) + delta[a0][c0]*(delta[a1][b0]*delta[d0][g0] + delta[a1][d0]*delta[b0][g0] + delta[a1][g0]*delta[b0][d0]) + delta[a0][d0]*(delta[a1][b0]*delta[c0][g0] + delta[a1][c0]*delta[b0][g0] + delta[a1][g0]*delta[b0][c0]) + delta[a0][g0]*(delta[a1][b0]*delta[c0][d0] + delta[a1][c0]*delta[b0][d0] + delta[a1][d0]*delta[b0][c0])) + PQ[g0]*(delta[a0][a1]*(delta[b0][c0]*delta[d0][d1] + delta[b0][d0]*delta[c0][d1] + delta[b0][d1]*delta[c0][d0]) + delta[a0][b0]*(delta[a1][c0]*delta[d0][d1] + delta[a1][d0]*delta[c0][d1] + delta[a1][d1]*delta[c0][d0]) + delta[a0][c0]*(delta[a1][b0]*delta[d0][d1] + delta[a1][d0]*delta[b0][d1] + delta[a1][d1]*delta[b0][d0]) + delta[a0][d0]*(delta[a1][b0]*delta[c0][d1] + delta[a1][c0]*delta[b0][d1] + delta[a1][d1]*delta[b0][c0]) + delta[a0][d1]*(delta[a1][b0]*delta[c0][d0] + delta[a1][c0]*delta[b0][d0] + delta[a1][d0]*delta[b0][c0])))

