delta[a0][d1] + QD_1*delta[a0][d0]) + PQ[d0]*(QC_0*delta[a0][d1] + QD_1*delta[a0][c0]) + PQ[d1]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0])) + PQ[g0]*(PA_0*(PQ[c0]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + PQ[d0]*(QC_0*delta[a1][d1] + QD_1*delta[a1][c0]) + PQ[d1]*(QC_0*delta[a1][d0] + QD_0*delta[a1][c0])) + PA_1*(PQ[c0]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + PQ[d0]*(QC_0*delta[a0][d1] + QD_1*delta[a0][c0]) + PQ[d1]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0])))) - PB_1*(PB_y*PQ[a1]*(PA_0*(PQ[b0]*(PQ[c0]*(QD_0*delta[d1][g0] + QD_1*delta[d0][g0]) + PQ[d0]*(QC_0*delta[d1][g0] + QD_1*delta[c0][g0]) + PQ[d1]*(QC_0*delta[d0][g0] + QD_0*delta[c0][g0])) + PQ[g0]*(PQ[c0]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0]) + PQ[d0]*(QC_0*delta[b0][d1] + QD_1*delta[b0][c0]) + PQ[d1]*(QC_0*delta[b0][d0] + QD_0*delta[b0][c0]))) + (PA_x*PQ[b0] + PB_0*PQ[g0])*(PQ[c0]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + PQ[d0]*(QC_0*delta[a0][d1] + QD_1*delta[a0][c0]) + PQ[d1]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0]))) + PQ[b0]*(PA_0*(PQ[c0]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + PQ[d0]*(QC_0*delta[a1][d1] + QD_1*delta[a1][c0]) + PQ[d1]*(QC_0*delta[a1][d0] + QD_0*delta[a1][c0])) + PA_1*(PQ[c0]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + PQ[d0]*(QC_0*delta[a0][d1] + QD_1*delta[a0][c0]) + PQ[d1]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0])))*(PA_x*PQ[g1] + PB_y*PQ[g0])) - PQ[a0]*(PA_1*(PA_x*(PB_0*(PQ[b1]*(PQ[c0]*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1]) + PQ[d0]*(QC_0*delta[d1][g1] + QD_1*delta[c0][g1]) + PQ[d1]*(QC_0*delta[d0][g1] + QD_0*delta[c0][g1])) + PQ[g1]*(PQ[c0]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0]) + PQ[d0]*(QC_0*delta[b1][d1] + QD_1*delta[b1][c0]) + PQ[d1]*(QC_0*delta[b1][d0] + QD_0*delta[b1][c0]))) + PB_1*(PQ[b0]*(PQ[c0]*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1]) + PQ[d0]*(QC_0*delta[d1][g1] + QD_1*delta[c0][g1]) + PQ[d1]*(QC_0*delta[d0][g1] + QD_0*delta[c0][g1])) + PQ[g1]*(PQ[c0]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0]) + PQ[d0]*(QC_0*delta[b0][d1] + QD_1*delta[b0][c0]) + PQ[d1]*(QC_0*delta[b0][d0] + QD_0*delta[b0][c0]))) + PB_y*(PQ[b0]*(PQ[c0]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0]) + PQ[d0]*(QC_0*delta[b1][d1] + QD_1*delta[b1][c0]) + PQ[d1]*(QC_0*delta[b1][d0] + QD_0*delta[b1][c0])) + PQ[b1]*(PQ[c0]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0]) + PQ[d0]*(QC_0*delta[b0][d1] + QD_1*delta[b0][c0]) + PQ[d1]*(QC_0*delta[b0][d0] + QD_0*delta[b0][c0])))) + PB_y*(PB_0*(PQ[b1]*(PQ[c0]*(QD_0*delta[d1][g0] + QD_1*delta[d0][g0]) + PQ[d0]*(QC_0*delta[d1][g0] + QD_1*delta[c0][g0]) + PQ[d1]*(QC_0*delta[d0][g0] + QD_0*delta[c0][g0])) + PQ[g0]*(PQ[c0]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0]) + PQ[d0]*(QC_0*delta[b1][d1] + QD_1*delta[b1][c0]) + PQ[d1]*(QC_0*delta[b1][d0] + QD_0*delta[b1][c0]))) + PB_1*(PQ[b0]*(PQ[c0]*(QD_0*delta[d1][g0] + QD_1*delta[d0][g0]) + PQ[d0]*(QC_0*delta[d1][g0] + QD_1*delta[c0][g0]) + PQ[d1]*(QC_0*delta[d0][g0] + QD_0*delta[c0][g0])) + PQ[g0]*(PQ[c0]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0]) + PQ[d0]*(QC_0*delta[b0][d1] + QD_1*delta[b0][c0]) + PQ[d1]*(QC_0*delta[b0][d0] + QD_0*delta[b0][c0]))))) + PA_x*PB_y*(PB_0*(PQ[a1]*(PQ[c0]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0]) + PQ[d0]*(QC_0*delta[b1][d1] + QD_1*delta[b1][c0]) + PQ[d1]*(QC_0*delta[b1][d0] + QD_0*delta[b1][c0])) + PQ[b1]*(PQ[c0]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + PQ[d0]*(QC_0*delta[a1][d1] + QD_1*delta[a1][c0]) + PQ[d1]*(QC_0*delta[a1][d0] + QD_0*delta[a1][c0]))) + PB_1*(PQ[a1]*(PQ[c0]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0]) + PQ[d0]*(QC_0*delta[b0][d1] + QD_1*delta[b0][c0]) + PQ[d1]*(QC_0*delta[b0][d0] + QD_0*delta[b0][c0])) + PQ[b0]*(PQ[c0]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + PQ[d0]*(QC_0*delta[a1][d1] + QD_1*delta[a1][c0]) + PQ[d1]*(QC_0*delta[a1][d0] + QD_0*delta[a1][c0])))) + PB_0*PB_1*(PA_1*(PQ[g0]*(PQ[c0]*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1]) + PQ[d0]*(QC_0*delta[d1][g1] + QD_1*delta[c0][g1]) + PQ[d1]*(QC_0*delta[d0][g1] + QD_0*delta[c0][g1])) + PQ[g1]*(PQ[c0]*(QD_0*delta[d1][g0] + QD_1*delta[d0][g0]) + PQ[d0]*(QC_0*delta[d1][g0] + QD_1*delta[c