                        +PQ[a0]*(PQ[a1]*(PQ[c0]*(QD_0*(PQ[b0]*(delta[b1][d1]*delta[g0][g1] + delta[b1][g0]*delta[d1][g1] + delta[b1][g1]*delta[d1][g0]) + PQ[b1]*(delta[b0][d1]*delta[g0][g1] + delta[b0][g0]*delta[d1][g1] + delta[b0][g1]*delta[d1][g0]) + PQ[g0]*(delta[b0][b1]*delta[d1][g1] + delta[b0][d1]*delta[b1][g1] + delta[b0][g1]*delta[b1][d1]) + PQ[g1]*(delta[b0][b1]*delta[d1][g0] + delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1])) + QD_1*(PQ[b0]*(delta[b1][d0]*delta[g0][g1] + delta[b1][g0]*delta[d0][g1] + delta[b1][g1]*delta[d0][g0]) + PQ[b1]*(delta[b0][d0]*delta[g0][g1] + delta[b0][g0]*delta[d0][g1] + delta[b0][g1]*delta[d0][g0]) + PQ[g0]*(delta[b0][b1]*delta[d0][g1] + delta[b0][d0]*delta[b1][g1] + delta[b0][g1]*delta[b1][d0]) + PQ[g1]*(delta[b0][b1]*delta[d0][g0] + delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0]))) + PQ[d0]*(QC_0*(PQ[b0]*(delta[b1][d1]*delta[g0][g1] + delta[b1][g0]*delta[d1][g1] + delta[b1][g1]*delta[d1][g0]) + PQ[b1]*(delta[b0][d1]*delta[g0][g1] + delta[b0][g0]*delta[d1][g1] + delta[b0][g1]*delta[d1][g0]) + PQ[g0]*(delta[b0][b1]*delta[d1][g1] + delta[b0][d1]*delta[b1][g1] + delta[b0][g1]*delta[b1][d1]) + PQ[g1]*(delta[b0][b1]*delta[d1][g0] + delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1])) + QD_1*(PQ[b0]*(delta[b1][c0]*delta[g0][g1] + delta[b1][g0]*delta[c0][g1] + delta[b1][g1]*delta[c0][g0]) + PQ[b1]*(delta[b0][c0]*delta[g0][g1] + delta[b0][g0]*delta[c0][g1] + delta[b0][g1]*delta[c0][g0]) + PQ[g0]*(delta[b0][b1]*delta[c0][g1] + delta[b0][c0]*delta[b1][g1] + delta[b0][g1]*delta[b1][c0]) + PQ[g1]*(delta[b0][b1]*delta[c0][g0] + delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0]))) + PQ[d1]*(QC_0*(PQ[b0]*(delta[b1][d0]*delta[g0][g1] + delta[b1][g0]*delta[d0][g1] + delta[b1][g1]*delta[d0][g0]) + PQ[b1]*(delta[b0][d0]*delta[g0][g1] + delta[b0][g0]*delta[d0][g1] + delta[b0][g1]*delta[d0][g0]) + PQ[g0]*(delta[b0][b1]*delta[d0][g1] + delta[b0][d0]*delta[b1][g1] + delta[b0][g1]*delta[b1][d0]) + PQ[g1]*(delta[b0][