        double kl_factor = 2.0;

        // mu-lambda hessian

        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[3] * 0.5 * S1 * inv_S4 * inv_S4 * inv_S4 * a_k * (

                        +(PA_0*delta[a1][g0] + PA_1*delta[a0][g0])*(PQ[b0]*(delta[b1][c0]*(delta[d0][d1]*(PQ[g1] + QC_y) + delta[d0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[d0] + QD_0)) + delta[b1][d0]*(delta[c0][d1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[c0] + QC_0)) + delta[b1][d1]*(delta[c0][d0]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c0] + QC_0)) + delta[b1][g1]*(delta[c0][d0]*(PQ[d1] + QD_1) + delta[c0][d1]*(PQ[d0] + QD_0) + delta[d0][d1]*(PQ[c0] + QC_0))) + PQ[b1]*(delta[b0][c0]*(delta[d0][d1]*(PQ[g1] + QC_y) + delta[d0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[d0] + QD_0)) + delta[b0][d0]*(delta[c0][d1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[c0] + QC_0)) + delta[b0][d1]*(delta[c0][d0]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c0] + QC_0)) + delta[b0][g1]*(delta[c0][d0]*(PQ[d1] + QD_1) + delta[c0][d1]*(PQ[d0] + QD_0) + delta[d0][d1]*(PQ[c0] + QC_0)))) + (PB_0*(delta[b1][c0]*(delta[d0][d1]*(PQ[g1] + QC_y) + delta[d0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[d0] + QD_0)) + delta[b1][d0]*(delta[c0][d1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[c0] + QC_0)) + delta[b1][d1]*(delta[c0][d0]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c0] + QC_0)) + delta[b1][g1]*(delta[c0][d0]*(PQ[d1] + QD_1) + delta[c0][d1]*(PQ[d0] + QD_0) + delta[d0][d1]*(PQ[c0] + QC_0))) + PB_1*(delta[b0][c0]*(delta[d0][d1]*(PQ[g1] + QC_y) + delta[d0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[d0] + QD_0)) + delta[b0][d0]*(delta[c0][d1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[c0] + QC_0)) + delta[b0][d1]*(delta[c0][d0]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c0] + QC_0)) + delta[b0][g1]*(delta[c0][d0]*(PQ[d1] + QD_1) + delta[c0][d1]*(PQ[d0] + QD_0) + delta[d0][d1]*(PQ[c0] + QC_0))))*(PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0])

                        +delta[b0][b1]*(delta[a0][g0]*(PA_1 - PQ[a1]) + delta[a1][g0]*(PA_0 - PQ[a0]))*(PQ[c0]*(delta[d0][d1]*(PQ[g1] + QC_y) + delta[d0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[d0] + QD_0)) + PQ[d0]*(QC_0*delta[d1][g1] + delta[c0][d1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d1] + QD_1)) + PQ[d1]*(QC_0*delta[d0][g1] + QD_0*delta[c0][g1] + delta[c0][d0]*(PQ[g1] + QC_y)) + PQ[g1]*(QC_0*delta[d0][d1] + QD_0*delta[c0][d1] + QD_1*delta[c0][d0]))

                        +(PA_0*delta[a1][g0] + PA_1*delta[a0][g0])*(PQ[c0]*(QC_y*(delta[b0][d0]*delta[b1][d1] + delta[b0][d1]*delta[b1][d0]) + QD_0*(delta[b0][d1]*delta[b1][g1] + delta[b0][g1]*delta[b1][d1]) + QD_1*(delta[b0][d0]*delta[b1][g1] + delta[b0][g1]*delta[b1][d0])) + PQ[d0]*(QC_0*(delta[b0][d1]*delta[b1][g1] + delta[b0][g1]*delta[b1][d1]) + QC_y*(delta[b0][c0]*delta[b1][d1] + delta[b0][d1]*delta[b1][c0]) + QD_1*(delta[b0][c0]*delta[b1][g1] + delta[b0][g1]*delta[b1][c0])) + PQ[d1]*(QC_0*(delta[b0][d0]*delta[b1][g1] + delta[b0][g1]*delta[b1][d0]) + QC_y*(delta[b0][c0]*delta[b1][d0] + delta[b0][d0]*delta[b1][c0]) + QD_0*(delta[b0][c0]*delta[b1][g1] + delta[b0][g1]*delta[b1][c0])) + PQ[g1]*(QC_0*(delta[b0][d0]*delta[b1][d1] + delta[b0][d1]*delta[b1][d0]) + QD_0*(delta[b0][c0]*delta[b1][d1] + delta[b0][d1]*delta[b1][c0]) + QD_1*(delta[b0][c0]*delta[b1][d0] + delta[b0][d0]*delta[b1][c0])))

                        +2.0*(PB_1*PQ[b0]*(PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0]) + PQ[b1]*(PB_0*(PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0]) + PQ[b0]*(PA_0*delta[a1][g0] + PA_1*delta[a0][g0])))*(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1] + delta[c0][g1]*delta[d0][d1])

                        +(PB_0*PQ[b1] + PB_1*PQ[b0])*(delta[a0][g0]*(delta[a1][c0]*(delta[d0][d1]*(PQ[g1] + QC_y) + delta[d0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[d0] + QD_0)) + delta[a1][d0]*(delta[c0][d1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[c0] + QC_0)) + delta[a1][d1]*(delta[c0][d0]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c0] + QC_0)) + delta[a1][g1]*(delta[c0][d0]*(PQ[d1] + QD_1) + delta[c0][d1]*(PQ[d0] + QD_0) + delta[d0][d1]*(PQ[c0] + QC_0))) + delta[a1][g0]*(delta[a0][c0]*(delta[d0][d1]*(PQ[g1] + QC_y) + delta[d0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[d0] + QD_0)) + delta[a0][d0]*(delta[c0][d1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[c0] + QC_0)) + delta[a0][d1]*(delta[c0][d0]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c0] + QC_0)) + delta[a0][g1]*(delta[c0][d0]*(PQ[d1] + QD_1) + delta[c0][d1]*(PQ[d0] + QD_0) + delta[d0][d1]*(PQ[c0] + QC_0))))

                        +(delta[a0][g0]*(delta[a1][b0]*(PB_1 - PQ[b1]) + delta[a1][b1]*(PB_0 - PQ[b0])) + delta[a1][g0]*(delta[a0][b0]*(PB_1 - PQ[b1]) + delta[a0][b1]*(PB_0 - PQ[b0])))*(PQ[c0]*(delta[d0][d1]*(PQ[g1] + QC_y) + delta[d0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[d0] + QD_0)) + PQ[d0]*(QC_0*delta[d1][g1] + delta[c0][d1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d1] + QD_1)) + PQ[d1]*(QC_0*delta[d0][g1] + QD_0*delta[c0][g1] + delta[c0][d0]*(PQ[g1] + QC_y)) + PQ[g1]*(QC_0*delta[d0][d1] + QD_0*delta[c0][d1] + QD_1*delta[c0][d0]))

                        +(PB_0*PQ[c0]*QC_y + PB_0*PQ[g1]*QC_0)*(delta[a0][d0]*delta[a1][g0]*delta[b1][d1] + delta[a0][d1]*delta[a1][g0]*delta[b1][d0] + delta[a0][g0]*delta[a1][d0]*delta[b1][d1] + delta[a0][g0]*delta[a1][d1]*delta[b1][d0]) + (PB_0*PQ[c0]*QD_0 + PB_0*PQ[d0]*QC_0)*(delta[a0][d1]*delta[a1][g0]*delta[b1][g1] + delta[a0][g0]*delta[a1][d1]*delta[b1][g1] + delta[a0][g0]*delta[a1][g1]*delta[b1][d1] + delta[a0][g1]*delta[a1][g0]*delta[b1][d1]) + (PB_0*PQ[c0]*QD_1 + PB_0*PQ[d1]*QC_0)*(delta[a0][d0]*delta[a1][g0]*delta[b1][g1] + delta[a0][g0]*delta[a1][d0]*delta[b1][g1] + delta[a0][g0]*delta[a1][g1]*delta[b1][d0] + delta[a0][g1]*delta[a1][g0]*delta[b1][d0]) + (PB_0*PQ[d0]*QC_y + PB_0*PQ[g1]*QD_0)*(delta[a0][c0]*delta[a1][g0]*delta[b1][d1] + delta[a0][d1]*delta[a1][g0]*delta[b1][c0] + delta[a0][g0]*delta[a1][c0]*delta[b1][d1] + delta[a0][g0]*delta[a1][d1]*delta[b1][c0]) + (PB_0*PQ[d0]*QD_1 + PB_0*PQ[d1]*QD_0)*(delta[a0][c0]*delta[a1][g0]*delta[b1][g1] + delta[a0][g0]*delta[a1][c0]*delta[b1][g1] + delta[a0][g0]*delta[a1][g1]*delta[b1][c0] + delta[a0][g1]*delta[a1][g0]*delta[b1][c0]) + (PB_0*PQ[d1]*QC_y + PB_0*PQ[g1]*QD_1)*(delta[a0][c0]*delta[a1][g0]*delta[b1][d0] + delta[a0][d0]*delta[a1][g0]*delta[b1][c0] + delta[a0][g0]*delta[a1][c0]*delta[b1][d0] + delta[a0][g0]*delta[a1][d0]*delta[b1][c0]) + (PB_1*PQ[c0]*QC_y + PB_1*PQ[g1]*QC_0)*(delta[a0][d0]*delta[a1][g0]*delta[b0][d1] + delta[a0][d1]*delta[a1][g0]*delta[b0][d0] + delta[a0][g0]*delta[a1][d0]*delta[b0][d1] + delta[a0][g0]*delta[a1][d1]*delta[b0][d0]) + (PB_1*PQ[c0]*QD_0 + PB_1*PQ[d0]*QC_0)*(delta[a0][d1]*delta[a1][g0]*delta[b0][g1] + delta[a0][g0]*delta[a1][d1]*delta[b0][g1] + delta[a0][g0]*delta[a1][g1]*delta[b0][d1] + delta[a0][g1]*delta[a1][g0]*delta[b0][d1]) + (PB_1*PQ[c0]*QD_1 + PB_1*PQ[d1]*QC_0)*(delta[a0][d0]*delta[a1][g0]*delta[b0][g1] + delta[a0][g0]*delta[a1][d0]*delta[b0][g1] + delta[a0][g0]*delta[a1][g1]*delta[b0][d0] + delta[a0][g1]*delta[a1][g0]*delta[b0][d0]) + (PB_1*PQ[d0]*QC_y + PB_1*PQ[g1]*QD_0)*(delta[a0][c0]*delta[a1][g0]*delta[b0][d1] + delta[a0][d1]*delta[a1][g0]*delta[b0][c0] + delta[a0][g0]*delta[a1][c0]*delta[b0][d1] + delta[a0][g0]*delta[a1][d1]*delta[b0][c0]) + (PB_1*PQ[d0]*QD_1 + PB_1*PQ[d1]*QD_0)*(delta[a0][c0]*delta[a1][g0]*delta[b0][g1] + delta[a0][g0]*delta[a1][c0]*delta[b0][g1] + delta[a0][g0]*delta[a1][g1]*delta[b0][c0] + delta[a0][g1]*delta[a1][g0]*delta[b0][c0]) + (PB_1*PQ[d1]*QC_y + PB_1*PQ[g1]*QD_1)*(delta[a0][c0]*delta[a1][g0]*delta[b0][d0] + delta[a0][d0]*delta[a1][g0]*delta[b0][c0] + delta[a0][g0]*delta[a1][c0]*delta[b0][d0] + delta[a0][g0]*delta[a1][d0]*delta[b0][c0])

                        +(-PQ[c0]*PQ[d0]*QC_y - PQ[c0]*PQ[g1]*QD_0 - PQ[d0]*PQ[g1]*QC_0)*(delta[a0][b0]*delta[a1][g0]*delta[b1][d1] + delta[a0][b1]*delta[a1][g0]*delta[b0][d1] + delta[a0][d1]*delta[a1][g0]*delta[b0][b1] + delta[a0][g0]*delta[a1][b0]*delta[b1][d1] + delta[a0][g0]*delta[a1][b1]*delta[b0][d1] + delta[a0][g0]*delta[a1][d1]*delta[b0][b1]) + (-PQ[c0]*PQ[d0]*QD_1 - PQ[c0]*PQ[d1]*QD_0 - PQ[d0]*PQ[d1]*QC_0)*(delta[a0][b0]*delta[a1][g0]*delta[b1][g1] + delta[a0][b1]*delta[a1][g0]*delta[b0][g1] + delta[a0][g0]*delta[a1][b0]*delta[b1][g1] + delta[a0][g0]*delta[a1][b1]*delta[b0][g1] + delta[a0][g0]*delta[a1][g1]*delta[b0][b1] + delta[a0][g1]*delta[a1][g0]*delta[b0][b1]) + (-PQ[c0]*PQ[d1]*QC_y - PQ[c0]*PQ[g1]*QD_1 - PQ[d1]*PQ[g1]*QC_0)*(delta[a0][b0]*delta[a1][g0]*delta[b1][d0] + delta[a0][b1]*delta[a1][g0]*delta[b0][d0] + delta[a0][d0]*delta[a1][g0]*delta[b0][b1] + delta[a0][g0]*delta[a1][b0]*delta[b1][d0] + delta[a0][g0]*delta[a1][b1]*delta[b0][d0] + delta[a0][g0]*delta[a1][d0]*delta[b0][b1]) + (-PQ[d0]*PQ[d1]*QC_y - PQ[d0]*PQ[g1]*QD_1 - PQ[d1]*PQ[g1]*QD_0)*(delta[a0][b0]*delta[a1][g0]*delta[b1][c0] + delta[a0][b1]*delta[a1][g0]*delta[b0][c0] + delta[a0][c0]*delta[a1][g0]*delta[b0][b1] + delta[a0][g0]*delta[a1][b0]*delta[b1][c0] + delta[a0][g0]*delta[a1][b1]*delta[b0][c0] + delta[a0][g0]*delta[a1][c0]*delta[b0][b1])

                    )


                );

        ERIs[threadIdx.y] += eri_ijkl * pd_mat_D[kl] * kl_factor;
    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < dd_prim_pair_count_local))
    {
        double hess_ik_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM_LARGE; n++)
        {
            hess_ik_xy += ERIs[n];
        }

        atomicAdd(
            hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + i] * natoms + atom_idx_k,
            hess_ik_xy * ij_factor_D * 2.0 * prefac_coulomb);
    }

    __syncthreads();

    }
}

__global__ void __launch_bounds__(TILE_SIZE_J)
computeCoulombHessianDDPD_IK_25(double*         hess_xy,
                               double*         hess_yx,
                               const uint32_t  hess_cart_ind_0,
                               const uint32_t  hess_cart_ind_1,
                               const double    prefac_coulomb,
                               const double*   p_prim_info,
                               const uint32_t  p_prim_count,
                               const double*   d_prim_info,
                               const uint32_t  d_prim_count,
                               const double*   dd_mat_D_local,
                               const double*   pd_mat_D,
                               const double*   dd_mat_Q_local,
                               const double*   pd_mat_Q,
                               const uint32_t* dd_first_inds_local,
                               const uint32_t* dd_second_inds_local,
                               const double*   dd_pair_data_local,
                               const uint32_t  dd_prim_pair_count_local,
                               const uint32_t* pd_first_inds,
                               const uint32_t* pd_second_inds,
                               const double*   pd_pair_data,
                               const uint32_t  pd_prim_pair_count,
                               const uint32_t* prim_cart_ao_to_atom_inds,
                               const uint32_t  natoms,
                               const uint32_t* d_kl_inds_for_atom_k,
                               const uint32_t* d_kl_counts_for_atom_k,
                               const uint32_t* d_kl_displs_for_atom_k,
                               const uint32_t  s_prim_count,
                               const double*   boys_func_table,
                               const double*   boys_func_ft,
                               const double    eri_threshold)
{
    // each thread row scans over [ij|??] and sum up to a primitive J matrix element
    // J. Chem. Theory Comput. 2009, 5, 4, 1004-1015

    __shared__ double   ERIs[TILE_DIM_LARGE + 1];
    __shared__ uint32_t d_cart_inds[6][2];
    __shared__ double   delta[3][3];
    __shared__ uint32_t g0, g1;

    __shared__ double a_i, a_j, r_i[3], r_j[3], S_ij_00, S1, inv_S1, ij_factor_D;
    __shared__ double PA_0, PA_1, PB_0, PB_1, PA_x;
    __shared__ uint32_t i, j, a0, a1, b0, b1;

    ERIs[threadIdx.y] = 0.0;

    const uint32_t ij = blockDim.x * blockIdx.x + threadIdx.x;

    if ((threadIdx.y == 0) && (threadIdx.x == 0))
    {
        d_cart_inds[0][0] = 0; d_cart_inds[0][1] = 0;
        d_cart_inds[1][0] = 0; d_cart_inds[1][1] = 1;
        d_cart_inds[2][0] = 0; d_cart_inds[2][1] = 2;
        d_cart_inds[3][0] = 1; d_cart_inds[3][1] = 1;
        d_cart_inds[4][0] = 1; d_cart_inds[4][1] = 2;
        d_cart_inds[5][0] = 2; d_cart_inds[5][1] = 2;

        delta[0][0] = 1.0; delta[0][1] = 0.0; delta[0][2] = 0.0;
        delta[1][0] = 0.0; delta[1][1] = 1.0; delta[1][2] = 0.0;
        delta[2][0] = 0.0; delta[2][1] = 0.0; delta[2][2] = 1.0;

        g0 = hess_cart_ind_0;
        g1 = hess_cart_ind_1;

        if (ij < dd_prim_pair_count_local)
        {
            i = dd_first_inds_local[ij];
            j = dd_second_inds_local[ij];

            a_i = d_prim_info[i / 6 + d_prim_count * 0];

            r_i[0] = d_prim_info[i / 6 + d_prim_count * 2];
            r_i[1] = d_prim_info[i / 6 + d_prim_count * 3];
            r_i[2] = d_prim_info[i / 6 + d_prim_count * 4];

            a_j = d_prim_info[j / 6 + d_prim_count * 0];

            r_j[0] = d_prim_info[j / 6 + d_prim_count * 2];
            r_j[1] = d_prim_info[j / 6 + d_prim_count * 3];
            r_j[2] = d_prim_info[j / 6 + d_prim_count * 4];

            S1 = a_i + a_j;
            inv_S1 = 1.0 / S1;

            S_ij_00 = dd_pair_data_local[ij];

            ij_factor_D = (static_cast<double>(i != j) + 1.0) * dd_mat_D_local[ij];

        PA_x = (a_j  * inv_S1) * (r_j[g0] - r_i[g0]);

            a0 = d_cart_inds[i % 6][0];
            a1 = d_cart_inds[i % 6][1];
            b0 = d_cart_inds[j % 6][0];
            b1 = d_cart_inds[j % 6][1];

            PA_0 = (a_j  * inv_S1) * (r_j[a0] - r_i[a0]);
            PA_1 = (a_j  * inv_S1) * (r_j[a1] - r_i[a1]);
            PB_0 = (-a_i * inv_S1) * (r_j[b0] - r_i[b0]);
            PB_1 = (-a_i * inv_S1) * (r_j[b1] - r_i[b1]);

        }
    }

    __syncthreads();

    for (uint32_t atom_idx_k = 0; atom_idx_k < natoms; atom_idx_k++)
    {

    ERIs[threadIdx.y] = 0.0;

    __syncthreads();

    const auto kl_pair_count = d_kl_counts_for_atom_k[atom_idx_k];
