[a1][d1] + QD_1*delta[a1][g1]) + PQ[d1]*(QC_y*delta[a1][d0] + QD_0*delta[a1][g1]) + PQ[g1]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0])) + QC_y*(PQ[c0]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + delta[a1][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))))) + QD_0*QD_1*(PA_1*(PA_x*(PQ[b0]*(PQ[c0]*delta[b1][g1] + PQ[g1]*delta[b1][c0]) + PQ[b1]*(PQ[c0]*delta[b0][g1] + PQ[g1]*delta[b0][c0])) + PB_0*(PQ[b1]*(PQ[c0]*delta[g0][g1] + PQ[g1]*delta[c0][g0]) + PQ[g0]*(PQ[c0]*delta[b1][g1] + PQ[g1]*delta[b1][c0])) + PB_1*(PQ[b0]*(PQ[c0]*delta[g0][g1] + PQ[g1]*delta[c0][g0]) + PQ[g0]*(PQ[c0]*delta[b0][g1] + PQ[g1]*delta[b0][c0]))) + PB_1*(PA_x*(PQ[a1]*(PQ[c0]*delta[b0][g1] + PQ[g1]*delta[b0][c0]) + PQ[b0]*(PQ[c0]*delta[a1][g1] + PQ[g1]*delta[a1][c0])) + PB_0*(PQ[a1]*(PQ[c0]*delta[g0][g1] + PQ[g1]*delta[c0][g0]) + PQ[g0]*(PQ[c0]*delta[a1][g1] + PQ[g1]*delta[a1][c0]))))) - PA_1*PB_1*(PA_0*(PQ[b0]*(QC_0*(PQ[d0]*(QC_y*delta[d1][g0] + QD_1*delta[g0][g1]) + PQ[d1]*(QC_y*delta[d0][g0] + QD_0*delta[g0][g1]) + PQ[g1]*(QD_0*delta[d1][g0] + QD_1*delta[d0][g0])) + QC_y*(PQ[c0]*(QD_0*delta[d1][g0] + QD_1*delta[d0][g0]) + delta[c0][g0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + PQ[g0]*(QC_0*(PQ[d0]*(QC_y*delta[b0][d1] + QD_1*delta[b0][g1]) + PQ[d1]*(QC_y*delta[b0][d0] + QD_0*delta[b0][g1]) + PQ[g1]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0])) + QC_y*(PQ[c0]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0]) + delta[b0][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0)))) + PA_x*(PQ[a0]*(QC_0*(PQ[d0]*(QC_y*delta[b0][d1] + QD_1*delta[b0][g1]) + PQ[d1]*(QC_y*delta[b0][d0] + QD_0*delta[b0][g1]) + PQ[g1]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0])) + QC_y*(PQ[c0]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0]) + delta[b0][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + PQ[b0]*(QC_0*(PQ[d0]*(QC_y*delta[a0][d1] + QD_1*delta[a0][g1]) + PQ[d1]*(QC_y*delta[a0][d0] + QD_0*delta[a0][g1]) + PQ[g1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0])) + QC_y*(PQ[c0]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + delta[a0][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0)))) + PB_0*(PQ[a0]*(QC_0*(PQ[d0]*(QC_y*delta[d1][g0] + QD_1*delta[g0][g1]) + PQ[d1]*(QC_y*delta[d0][g0] + QD_0*delta[g0][g1]) + PQ[g1]*(QD_0*delta[d1][g0] + QD_1*delta[d0][g0])) + QC_y*(PQ[c0]*(QD_0*delta[d1][g0] + QD_1*delta[d0][g0]) + delta[c0][g0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + PQ[g0]*(QC_0*(PQ[d0]*(QC_y*delta[a0][d1] + QD_1*delta[a0][g1]) + PQ[d1]*(QC_y*delta[a0][d0] + QD_0*delta[a0][g1]) + PQ[g1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0])) + QC_y*(PQ[c0]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + delta[a0][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0)))) + QD_0*QD_1*(PA_x*(PQ[a0]*(PQ[c0]*delta[b0][g1] + PQ[g1]*delta[b0][c0]) + PQ[b0]*(PQ[c0]*delta[a0][g1] + PQ[g1]*delta[a0][c0])) + PB_0*(PQ[a0]*(PQ[c0]*delta[g0][g1] + PQ[g1]*delta[c0][g0]) + PQ[g0]*(PQ[c0]*delta[a0][g1] + PQ[g1]*delta[a0][c0])))) - PA_x*PB_0*(PA_0*(PQ[a1]*(QC_0*(PQ[d0]*(QC_y*delta[b1][d1] + QD_1*delta[b1][g1]) + PQ[d1]*(QC_y*delta[b1][d0] + QD_0*delta[b1][g1]) + PQ[g1]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0])) + QC_y*(PQ[c0]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0]) + delta[b1][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + PQ[b1]*(QC_0*(PQ[d0]*(QC_y*delta[a1][d1] + QD_1*delta[a1][g1]) + PQ[d1]*(QC_y*delta[a1][d0] + QD_0*delta[a1][g1]) + PQ[g1]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0])) + QC_y*(PQ[c0]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + delta[a1][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0)))) + PA_1*(PQ[a0]*(QC_0*(PQ[d0]*(QC_y*delta[b1][d1] + QD_1*delta[b1][g1]) + PQ[d1]*(QC_y*delta[b1][d0] + QD_0*delta[b1][g1]) + PQ[g1]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0])) + QC_y*(PQ[c0]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0]) + delta[b1][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + PQ[b1]*(QC_0*(PQ[d0]*(QC_y*delta[a0][d1] + QD_1*delta[a0][g1]) + PQ[d1]*(QC_y*delta[a0][d0] + QD_0*delta[a0][g1]) + PQ[g1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0])) + QC_y*(PQ[c0]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + delta[a0][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0)))) + PB_1*(PQ[a0]*(QC_0*(PQ[d0]*(QC_y*delta[a1][d1] + QD_1*delta[a1][g1]) + PQ[d1]*(QC_y*delta[a1][d0] + QD_0*delta[a1][g1]) + PQ[g1]*(QD_