                        +delta[c0][g1]*(PQ[d0]*QD_1 + PQ[d1]*QD_0)*(PA_0*(PA_1*PQ[b0]*(PA_x*PQ[b1] + PB_1*PQ[g0]) + PB_1*PQ[a1]*(PA_x*PQ[b0] + PB_0*PQ[g0])) + PA_1*PA_x*PQ[a0]*(PB_0*PQ[b1] + PB_1*PQ[b0]) + PB_0*(PA_0*PQ[b1] + PB_1*PQ[a0])*(PA_1*PQ[g0] + PA_x*PQ[a1]))

                    )

                    + F9_t[3] * 2.0 * S1 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * a_k * (

                        +(PB_1*PQ[b0]*(PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0]) + PQ[b1]*(PB_0*(PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0]) + PQ[b0]*(PA_0*delta[a1][g0] + PA_1*delta[a0][g0])))*(QC_0*QD_1*(PQ[d0]*QC_y + PQ[g1]*QD_0) + QC_y*QD_0*(PQ[c0]*QD_1 + PQ[d1]*QC_0))

                    )

