                    )

                    + F9_t[3] * (-2.0) * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * a_i * (

                        +QD_0*QD_1*delta[c0][g1]*(PA_1*PQ[a0]*PQ[b0]*(PA_x*PQ[b1] + PB_1*PQ[g0]) + PQ[a1]*(PA_0*PQ[g0]*(PB_0*PQ[b1] + PB_1*PQ[b0]) + PB_1*PQ[a0]*(PA_x*PQ[b0] + PB_0*PQ[g0])) + PQ[b1]*(PA_0*PQ[b0] + PB_0*PQ[a0])*(PA_1*PQ[g0] + PA_x*PQ[a1]))

