        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[5] * 0.5 * S1 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_i * a_k * (

