PB_x*(delta[a0][b0]*delta[b1][d0] + delta[a0][b1]*delta[b0][d0] + delta[a0][d0]*delta[b0][b1]))) + (PQ[d0]*QD_1 + PQ[d1]*QD_0)*(PB_0*(delta[a0][b1]*delta[c0][g0] + delta[a0][c0]*delta[b1][g0] + delta[a0][g0]*delta[b1][c0]) + PB_1*(delta[a0][b0]*delta[c0][g0] + delta[a0][c0]*delta[b0][g0] + delta[a0][g0]*delta[b0][c0]) + PB_x*(delta[a0][b0]*delta[b1][c0] + delta[a0][b1]*delta[b0][c0] + delta[a0][c0]*delta[b0][b1])))) - PB_0*(PB_1*(QC_0*(PQ[d0]*(QC_y*(delta[a0][a1]*delta[d1][g0] + delta[a0][d1]*delta[a1][g0] + delta[a0][g0]*delta[a1][d1]) + QD_1*(delta[a0][a1]*delta[g0][g1] + delta[a0][g0]*delta[a1][g1] + delta[a0][g1]*delta[a1][g0])) + PQ[d1]*(QC_y*(delta[a0][a1]*delta[d0][g0] + delta[a0][d0]*delta[a1][g0] + delta[a0][g0]*delta[a1][d0]) + QD_0*(delta[a0][a1]*delta[g0][g1] + delta[a0][g0]*delta[a1][g1] + delta[a0][g1]*delta[a1][g0])) + PQ[g1]*(QD_0*(delta[a0][a1]*delta[d1][g0] + delta[a0][d1]*delta[a1][g0] + delta[a0][g0]*delta[a1][d1]) + QD_1*(delta[a0][a1]*delta[d0][g0] + delta[a0][d0]*delta[a1][g0] + delta[a0][g0]*delta[a1][d0]))) + QC_y*(PQ[c0]*(QD_0*(delta[a0][a1]*delta[d1][g0] + delta[a0][d1]*delta[a1][g0] + delta[a0][g0]*delta[a1][d1]) + QD_1*(delta[a0][a1]*delta[d0][g0] + delta[a0][d0]*delta[a1][g0] + delta[a0][g0]*delta[a1][d0])) + (PQ[d0]*QD_1 + PQ[d1]*QD_0)*(delta[a0][a1]*delta[c0][g0] + delta[a0][c0]*delta[a1][g0] + delta[a0][g0]*delta[a1][c0]))) + PB_x*(QC_0*(PQ[d0]*(QC_y*(delta[a0][a1]*delta[b1][d1] + delta[a0][b1]*delta[a1][d1] + delta[a0][d1]*delta[a1][b1]) + QD_1*(delta[a0][a1]*delta[b1][g1] + delta[a0][b1]*delta[a1][g1] + delta[a0][g1]*delta[a1][b1])) + PQ[d1]*(QC_y*(delta[a0][a1]*delta[b1][d0] + delta[a0][b1]*delta[a1][d0] + delta[a0][d0]*delta[a1][b1]) + QD_0*(delta[a0][a1]*delta[b1][g1] + delta[a0][b1]*delta[a1][g1] + delta[a0][g1]*delta[a1][b1])) + PQ[g1]*(QD_0*(delta[a0][a1]*delta[b1][d1] + delta[a0][b1]*delta[a1][d1] + delta[a0][d1]*delta[a1][b1]) + QD_1*(delta[a0][a1]*delta[b1][d0] + delta[a0][b1]*delta[a1][d0] + delta[a0][d0]*delta[a1][b1]))) + QC_y*(PQ[c0]*(QD_0*(delta[a0][a1]*delta[b1][d1] + delta[a0][b1]*delta[a1][d1] + delta[a0][d1]*delta[a1][b1]) + QD_1*(delta[a0][a1]*delta[b1][d0] + delta[a0][b1]*delta[a1][d0] + delta[a0][d0]*delta[a1][b1])) + (PQ[d0]*QD_1 + PQ[d1]*QD_0)*(delta[a0][a1]*delta[b1][c0] + delta[a0][b1]*delta[a1][c0] + delta[a0][c0]*delta[a1][b1])))) - PB_1*PB_x*(QC_0*(PQ[d0]*(QC_y*(delta[a0][a1]*delta[b0][d1] + delta[a0][b0]*delta[a1][d1] + delta[a0][d1]*delta[a1][b0]) + QD_1*(delta[a0][a1]*delta[b0][g1] + delta[a0][b0]*delta[a1][g1] + delta[a0][g1]*delta[a1][b0])) + PQ[d1]*(QC_y*(delta[a0][a1]*delta[b0][d0] + delta[a0][b0]*delta[a1][d0] + delta[a0][d0]*delta[a1][b0]) + QD_0*(delta[a0][a1]*delta[b0][g1] + delta[a0][b0]*delta[a1][g1] + delta[a0][g1]*delta[a1][b0])) + PQ[g1]*(QD_0*(delta[a0][a1]*delta[b0][d1] + delta[a0][b0]*delta[a1][d1] + delta[a0][d1]*delta[a1][b0]) + QD_1*(delta[a0][a1]*delta[b0][d0] + delta[a0][b0]*delta[a1][d0] + delta[a0][d0]*delta[a1][b0]))) + QC_y*(PQ[c0]*(QD_0*(delta[a0][a1]*delta[b0][d1] + delta[a0][b0]*delta[a1][d1] + delta[a0][d1]*delta[a1][b0]) + QD_1*(delta[a0][a1]*delta[b0][d0] + delta[a0][b0]*delta[a1][d0] + delta[a0][d0]*delta[a1][b0])) + (PQ[d0]*QD_1 + PQ[d1]*QD_0)*(delta[a0][a1]*delta[b0][c0] + delta[a0][b0]*delta[a1][c0] + delta[a0][c0]*delta[a1][b0]))) - QD_0*QD_1*(PA_0*(PQ[c0]*(PA_1*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PB_0*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + PB_1*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]) + PB_x*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1])) + PQ[g1]*(PA_1*(delta[b0][b1]*delta[c0][g0] + delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0]) + PB_0*(delta[a1][b1]*delta[c0][g0] + delta[a1][c0]*delta[b1][g0] + delta[a1][g0]*delta[b1][c0]) + PB_1*(delta[a1][b0]*delta[c0][g0] + delta[a1][c0]*delta[b0][g0] + delta[a1][g0]*delta[b0][c0]) + PB_x*(delta[a1][b0]*delta[b1][c0] + delta[a1][b1]*delta[b0][c0] + delta[a1][c0]*delta[b0][b1]))) + PA_1*(PQ[c0]*(PB_0*(delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) + PB_1*(delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0]) + PB_x*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1])) + PQ[g1]*(PB_0*(delta[a0][b1]*delta[c0][g0] + delta[a0][c0]*delta[b1][g0] + delta[a0][g0]*delta[b1][c0]) + PB_1*(delta[a0][b0]*delta[c0][g0] + delta[a0][c0]*delta[b0][g0] + delta[a0][g0]*delta[b0][c0]) + PB_x*(delta[a0][b0]*delta[b1][c0] + delta[a0][b1]*delta[b0][c0] + delta[a0][c0]*delta[b0][b1]))) + PB_0*(PB_1*(PQ[c0]*(delta[a0][a1]*delta[g0][g1] + delta[a0][g0]*delta[a1][g1] + delta[a0][g1]*delta[a1][g0]) + PQ[g1]*(delta[a0][a1]*delta[c0][g0] + delta[a0][c0]*delta[a1][g0] + delta[a0][g0]*delta[a1][c0])) + PB_x*(PQ[c0]*(delta[a0][a1]*delta[b1][g1] + delta[a0][b1]*delta[a1][g1] + delta[a0][g1]*delta[a1][b1]) + PQ[g1]*(delta[a0][a1]*delta[b1][c0] + delta[a0][b1]*delta[a1][c0] + delta[a0][c0]*delta[a1][b1]))) + PB_1*PB_x*(PQ[c0]*(delta[a0][a1]*delta[b0][g1] + delta[a0][b0]*delta[a1][g1] + delta[a0][g1]*delta[a1][b0]) + PQ[g1]*(delta[a0][a1]*delta[b0][c0] + delta[a0][b0]*delta[a1][c0] + delta[a0][c0]*delta[a1][b0])))

                        +(PQ[c0]*QC_y*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + PQ[d0]*QC_0*(PQ[d1]*QC_y + PQ[g1]*QD_1) + PQ[g1]*QD_0*(PQ[c0]*QD_1 + PQ[d1]*QC_0))*(PA_0*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + PA_1*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1]) + PB_0*(delta[a0][a1]*delta[b1][g0] + delta[a0][b1]*delta[a1][g0] + delta[a0][g0]*delta[a1][b1]) + PB_1*(delta[a0][a1]*delta[b0][g0] + delta[a0][b0]*delta[a1][g0] + delta[a0][g0]*delta[a1][b0]) + PB_x*(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0]))

