                        +PA_0*PA_1*PB_0*PB_1*PB_x*(PQ[c0]*(delta[d0][d1]*(PQ[g1] + QC_y) + delta[d0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[d0] + QD_0)) + PQ[d0]*(QC_0*delta[d1][g1] + delta[c0][d1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d1] + QD_1)) + PQ[d1]*(QC_0*delta[d0][g1] + QD_0*delta[c0][g1] + delta[c0][d0]*(PQ[g1] + QC_y)) + PQ[g1]*(QC_0*delta[d0][d1] + QD_0*delta[c0][d1] + QD_1*delta[c0][d0]))

