                    + F9_t[2] * (-1.0) * S1 * S1 * inv_S2 * inv_S4 * inv_S4 * a_k * (

                        +PA_0*PA_1*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0])*(PQ[c0]*(delta[d0][d1]*(PQ[g1] + QC_y) + delta[d0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[d0] + QD_0)) + PQ[d0]*(QC_0*delta[d1][g1] + delta[c0][d1]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[d1] + QD_1)) + PQ[d1]*(QC_0*delta[d0][g1] + QD_0*delta[c0][g1] + delta[c0][d0]*(PQ[g1] + QC_y)) + PQ[g1]*(QC_0*delta[d0][d1] + QD_0*delta[c0][d1] + QD_1*delta[c0][d0]))

                    )

                    + F9_t[2] * 2.0 * S1 * inv_S4 * inv_S4 * a_j * a_k * (

                        -(PA_0*PB_1*PB_x*(PA_1*PQ[b0] + PB_0*PQ[a1]) + PA_1*PB_0*(PA_0*(PB_1*PQ[g0] + PB_x*PQ[b1]) + PB_1*PB_x*PQ[a0]))*(QC_0*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1] + PQ[g1]*delta[d0][d1]) + QC_y*(delta[c0][d0]*(PQ[d1] + QD_1) + delta[c0][d1]*(PQ[d0] + QD_0) + delta[d0][d1]*(PQ[c0] + QC_0)) + QD_0*(PQ[d1]*delta[c0][g1] + PQ[g1]*delta[c0][d1] + delta[d1][g1]*(PQ[c0] + QC_0)) + QD_1*(PQ[g1]*delta[c0][d0] + delta[c0][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c0] + QC_0)))

                        -PA_0*PB_1*PB_x*(PA_1*(QC_0*(PQ[d0]*(QC_y*delta[b0][d1] + QD_1*delta[b0][g1]) + PQ[d1]*(QC_y*delta[b0][d0] + QD_0*delta[b0][g1]) + PQ[g1]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0])) + QC_y*(PQ[c0]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0]) + delta[b0][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + PB_0*(QC_0*(PQ[d0]*(QC_y*delta[a1][d1] + QD_1*delta[a1][g1]) + PQ[d1]*(QC_y*delta[a1][d0] + QD_0*delta[a1][g1]) + PQ[g1]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0])) + QC_y*(PQ[c0]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + delta[a1][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + QD_0*QD_1*(PA_1*(PQ[c0]*delta[b0][g1] + PQ[g1]*delta[b0][c0]) + PB_0*(PQ[c0]*delta[a1][g1] + PQ[g1]*delta[a1][c0]))) - PA_1*PB_0*(PA_0*(PB_1*(QC_0*(PQ[d0]*(QC_y*delta[d1][g0] + QD_1*delta[g0][g1]) + PQ[d1]*(QC_y*delta[d0][g0] + QD_0*delta[g0][g1]) + PQ[g1]*(QD_0*delta[d1][g0] + QD_1*delta[d0][g0])) + QC_y*(PQ[c0]*(QD_0*delta[d1][g0] + QD_1*delta[d0][g0]) + delta[c0][g0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + PB_x*(QC_0*(PQ[d0]*(QC_y*delta[b1][d1] + QD_1*delta[b1][g1]) + PQ[d1]*(QC_y*delta[b1][d0] + QD_0*delta[b1][g1]) + PQ[g1]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0])) + QC_y*(PQ[c0]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0]) + delta[b1][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + QD_0*QD_1*(PB_1*(PQ[c0]*delta[g0][g1] + PQ[g1]*delta[c0][g0]) + PB_x*(PQ[c0]*delta[b1][g1] + PQ[g1]*delta[b1][c0]))) + PB_1*PB_x*(QC_0*(PQ[d0]*(QC_y*delta[a0][d1] + QD_1*delta[a0][g1]) + PQ[d1]*(QC_y*delta[a0][d0] + QD_0*delta[a0][g1]) + PQ[g1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0])) + QC_y*(PQ[c0]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + delta[a0][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0)) + QD_0*QD_1*(PQ[c0]*delta[a0][g1] + PQ[g1]*delta[a0][c0])))

                        +(PA_0*(PA_1*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0] + PB_x*delta[b0][b1]) + PB_x*(PB_0*delta[a1][b1] + PB_1*delta[a1][b0])) + PA_1*PB_x*(PB_0*delta[a0][b1] + PB_1*delta[a0][b0]) + PB_0*PB_1*(PA_0*delta[a1][g0] + PA_1*delta[a0][g0] + PB_x*delta[a0][a1]))*(PQ[c0]*QC_y*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + PQ[d0]*QC_0*(PQ[d1]*QC_y + PQ[g1]*QD_1) + PQ[g1]*QD_0*(PQ[c0]*QD_1 + PQ[d1]*QC_0))

                    )

                    + F9_t[2] * S1 * inv_S4 * inv_S4 * a_j * (

                        +delta[c0][g1]*(PA_0*PB_1*PB_x*(PA_1*(PQ[d0]*delta[b0][d1] + PQ[d1]*delta[b0][d0]) + PB_0*(PQ[d0]*delta[a1][d1] + PQ[d1]*delta[a1][d0])) + PA_1*PB_0*(PA_0*(PB_1*(PQ[d0]*delta[d1][g0] + PQ[d1]*delta[d0][g0]) + PB_x*(PQ[d0]*delta[b1][d1] + PQ[d1]*delta[b1][d0])) + PB_1*PB_x*(PQ[d0]*delta[a0][d1] + PQ[d1]*delta[a0][d0])))

                        +delta[c0][g1]*delta[d0][d1]*(PA_0*PB_1*PB_x*(PA_1*PQ[b0] + PB_0*PQ[a1]) + PA_1*PB_0*(PA_0*(PB_1*PQ[g0] + PB_x*PQ[b1]) + PB_1*PB_x*PQ[a0]))

                        -PQ[d0]*PQ[d1]*delta[c0][g1]*(PA_0*(PA_1*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0] + PB_x*delta[b0][b1]) + PB_x*(PB_0*delta[a1][b1] + PB_1*delta[a1][b0])) + PA_1*PB_x*(PB_0*delta[a0][b1] + PB_1*delta[a0][b0]) + PB_0*PB_1*(PA_0*delta[a1][g0] + PA_1*delta[a0][g0] + PB_x*delta[a0][a1]))

                    )

                    + F9_t[2] * S1 * inv_S4 * inv_S4 * a_k * (

                        +(PA_0*(PA_1*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0]) + PQ[a1]*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0])) + PA_1*PQ[a0]*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0]))*(QC_0*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1] + PQ[g1]*delta[d0][d1]) + QC_y*(delta[c0][d0]*(PQ[d1] + QD_1) + delta[c0][d1]*(PQ[d0] + QD_0) + delta[d0][d1]*(PQ[c0] + QC_0)) + QD_0*(PQ[d1]*delta[c0][g1] + PQ[g1]*delta[c0][d1] + delta[d1][g1]*(PQ[c0] + QC_0)) + QD_1*(PQ[g1]*delta[c0][d0] + delta[c0][g1]*(PQ[d0] + QD_0) + delta[d0][g1]*(PQ[c0] + QC_0)))

                        +PA_0*PA_1*(QC_0*(PQ[d0]*(QC_y*(delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1]) + QD_1*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])) + PQ[d1]*(QC_y*(delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0]) + QD_0*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0])) + PQ[g1]*(QD_0*(delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1]) + QD_1*(delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0]))) + QC_y*(PQ[c0]*(QD_0*(delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1]) + QD_1*(delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0])) + (PQ[d0]*QD_1 + PQ[d1]*QD_0)*(delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0])) + QD_0*QD_1*(PQ[c0]*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PQ[g1]*(delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0])))

                        +(PB_0*delta[b1][g0] + PB_1*delta[b0][g0])*(PA_0*(QC_0*(PQ[d0]*(QC_y*delta[a1][d1] + QD_1*delta[a1][g1]) + PQ[d1]*(QC_y*delta[a1][d0] + QD_0*delta[a1][g1]) + PQ[g1]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0])) + QC_y*(PQ[c0]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + delta[a1][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + PA_1*(QC_0*(PQ[d0]*(QC_y*delta[a0][d1] + QD_1*delta[a0][g1]) + PQ[d1]*(QC_y*delta[a0][d0] + QD_0*delta[a0][g1]) + PQ[g1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0])) + QC_y*(PQ[c0]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + delta[a0][c0]*(PQ[d0]*QD_1 + PQ[d1]*QD_0))) + QD_0*QD_1*(PA_0*(PQ[c0]*delta[a1][g1] + PQ[g1]*delta[a1][c0]) + PA_1*(PQ[c0]*delta[a0][g1] + PQ[g1]*delta[a0][c0])))

                        -(PA_0*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0]) + PA_1*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0]))*(PQ[c0]*QC_y*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + PQ[d0]*QC_0*(PQ[d1]*QC_y + PQ[g1]*QD_1) + PQ[g1]*QD_0*(PQ[c0]*QD_1 + PQ[d1]*QC_0))

                        -delta[a0][a1]*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0])*(PQ[c0]*QC_y*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + PQ[d0]*QC_0*(PQ[d1]*QC_y + PQ[g1]*QD_1) + PQ[g1]*QD_0*(PQ[c0]*QD_1 + PQ[d1]*QC_0))

