                        -PA_0*PA_1*delta[c0][g1]*(PQ[d0]*(delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1]) + PQ[d1]*(delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0]))

