        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[3] * S1 * S1 * S2 * inv_S4 * inv_S4 * inv_S4 * (

                        +PQ[d0]*PQ[d1]*delta[c0][g1]*(PA_0*(PA_1*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0]) + PQ[a1]*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0])) + PA_1*PQ[a0]*(PB_0*delta[b1][g0] + PB_1*delta[b0][g0]))

                    )

                    + F9_t[3] * 4.0 * S1 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * a_j * a_k * (

                        -(QC_0*QD_1*(PQ[d0]*QC_y + PQ[g1]*QD_0) + QC_y*QD_0*(PQ[c0]*QD_1 + PQ[d1]*QC_0))*(PA_0*(PA_1*PQ[b1]*(PB_0*PQ[g0] + PB_x*PQ[b0]) + PB_1*PQ[b0]*(PA_1*PQ[g0] + PB_x*PQ[a1])) + PB_0*(PA_0*PQ[a1] + PA_1*PQ[a0])*(PB_1*PQ[g0] + PB_x*PQ[b1]) + PB_1*PB_x*PQ[a0]*(PA_1*PQ[b0] + PB_0*PQ[a1]))

