                        +QC_0*QC_y*QD_0*QD_1*(PA_1*PQ[a0]*PQ[b1]*(PB_0*PQ[g0] + PB_x*PQ[b0]) + PQ[a1]*(PA_0*PQ[g0]*(PB_0*PQ[b1] + PB_1*PQ[b0]) + PB_0*PQ[a0]*(PB_1*PQ[g0] + PB_x*PQ[b1])) + PQ[b0]*(PA_0*PQ[b1] + PB_1*PQ[a0])*(PA_1*PQ[g0] + PB_x*PQ[a1]))

                    )

                    + F9_t[3] * (-2.0) * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * a_j * (

                        +QD_0*QD_1*delta[c0][g1]*(PA_1*PQ[a0]*PQ[b1]*(PB_0*PQ[g0] + PB_x*PQ[b0]) + PQ[a1]*(PA_0*PQ[g0]*(PB_0*PQ[b1] + PB_1*PQ[b0]) + PB_0*PQ[a0]*(PB_1*PQ[g0] + PB_x*PQ[b1])) + PQ[b0]*(PA_0*PQ[b1] + PB_1*PQ[a0])*(PA_1*PQ[g0] + PB_x*PQ[a1]))

                    )

                    + F9_t[3] * (-2.0) * S2 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * a_k * (

                        +PQ[a0]*PQ[a1]*QC_0*QC_y*QD_0*QD_1*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0])

                    )


                );

        ERIs[threadIdx.y] += eri_ijkl * pd_mat_D[kl] * kl_factor;
    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < dd_prim_pair_count_local))
    {
        double hess_jk_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM_LARGE; n++)
        {
