                        +PQ[c0]*PQ[d0]*PQ[d1]*PQ[g1]*(PA_0*(PA_1*PQ[b1]*(PB_0*PQ[g0] + PB_x*PQ[b0]) + PB_1*PQ[b0]*(PA_1*PQ[g0] + PB_x*PQ[a1])) + PB_0*(PA_0*PQ[a1] + PA_1*PQ[a0])*(PB_1*PQ[g0] + PB_x*PQ[b1]) + PB_1*PB_x*PQ[a0]*(PA_1*PQ[b0] + PB_0*PQ[a1]))

