                        -delta[a0][g0]*(delta[a1][b0]*(PQ[c0]*(delta[b1][d0]*delta[d1][g1] + delta[b1][d1]*delta[d0][g1] + delta[b1][g1]*delta[d0][d1]) + PQ[d0]*(delta[b1][c0]*delta[d1][g1] + delta[b1][d1]*delta[c0][g1] + delta[b1][g1]*delta[c0][d1]) + PQ[d1]*(delta[b1][c0]*delta[d0][g1] + delta[b1][d0]*delta[c0][g1] + delta[b1][g1]*delta[c0][d0]) + PQ[g1]*(delta[b1][c0]*delta[d0][d1] + delta[b1][d0]*delta[c0][d1] + delta[b1][d1]*delta[c0][d0])) + delta[a1][b1]*(PQ[c0]*(delta[b0][d0]*delta[d1][g1] + delta[b0][d1]*delta[d0][g1] + delta[b0][g1]*delta[d0][d1]) + PQ[d0]*(delta[b0][c0]*delta[d1][g1] + delta[b0][d1]*delta[c0][g1] + delta[b0][g1]*delta[c0][d1]) + PQ[d1]*(delta[b0][c0]*delta[d0][g1] + delta[b0][d0]*delta[c0][g1] + delta[b0][g1]*delta[c0][d0]) + PQ[g1]*(delta[b0][c0]*delta[d0][d1] + delta[b0][d0]*delta[c0][d1] + delta[b0][d1]*delta[c0][d0])) + delta[b0][b1]*(PQ[c0]*(delta[a1][d0]*delta[d1][g1] + delta[a1][d1]*delta[d0][g1] + delta[a1][g1]*delta[d0][d1]) + PQ[d0]*(delta[a1][c0]*delta[d1][g1] + delta[a1][d1]*delta[c0][g1] + delta[a1][g1]*delta[c0][d1]) + PQ[d1]*(delta[a1][c0]*delta[d0][g1] + delta[a1][d0]*delta[c0][g1] + delta[a1][g1]*delta[c0][d0]) + PQ[g1]*(delta[a1][c0]*delta[d0][d1] + delta[a1][d0]*delta[c0][d1] + delta[a1][d1]*delta[c0][d0]))) - delta[a1][g0]*(delta[a0][b0]*(PQ[c0]*(delta[b1][d0]*delta[d1][g1] + delta[b1][d1]*delta[d0][g1] + delta[b1][g1]*delta[d0][d1]) + PQ[d0]*(delta[b1][c0]*delta[d1][g1] + delta[b1][d1]*delta[c0][g1] + delta[b1][g1]*delta[c0][d1]) + PQ[d1]*(delta[b1][c0]*delta[d0][g1] + delta[b1][d0]*delta[c0][g1] + delta[b1][g1]*delta[c0][d0]) + PQ[g1]*(delta[b1][c0]*delta[d0][d1] + delta[b1][d0]*delta[c0][d1] + delta[b1][d1]*delta[c0][d0])) + delta[a0][b1]*(PQ[c0]*(delta[b0][d0]*delta[d1][g1] + delta[b0][d1]*delta[d0][g1] + delta[b0][g1]*delta[d0][d1]) + PQ[d0]*(delta[b0][c0]*delta[d1][g1] + delta[b0][d1]*delta[c0][g1] + delta[b0][g1]*delta[c0][d1]) + PQ[d1]*(delta[b0][c0]*delta[d0][g1] + delta[b0][d0]*delta[c0][g1] + delta[b0][g1]*delta[c0][d0]) + PQ[g1]*(delta[b0][c0]*delta[d0][d1] + delta[b0][d0]*delta[c0][d1] + delta[b0][d1]*delta[c0][d0])) + delta[b0][b1]*(PQ[c0]*(delta[a0][d0]*delta[d1][g1] + delta[a0][d1]*delta[d0][g1] + delta[a0][g1]*delta[d0][d1]) + PQ[d0]*(delta[a0][c0]*delta[d1][g1] + delta[a0][d1]*delta[c0][g1] + delta[a0][g1]*delta[c0][d1]) + PQ[d1]*(delta[a0][c0]*delta[d0][g1] + delta[a0][d0]*delta[c0][g1] + delta[a0][g1]*delta[c0][d0]) + PQ[g1]*(delta[a0][c0]*delta[d0][d1] + delta[a0][d0]*delta[c0][d1] + delta[a0][d1]*delta[c0][d0])))

                        +(PA_0*delta[a1][g0] + PA_1*delta[a0][g0])*(delta[b0][c0]*(delta[b1][d0]*delta[d1][g1] + delta[b1][d1]*delta[d0][g1] + delta[b1][g1]*delta[d0][d1]) + delta[b0][d0]*(delta[b1][c0]*delta[d1][g1] + delta[b1][d1]*delta[c0][g1] + delta[b1][g1]*delta[c0][d1]) + delta[b0][d1]*(delta[b1][c0]*delta[d0][g1] + delta[b1][d0]*delta[c0][g1] + delta[b1][g1]*delta[c0][d0]) + delta[b0][g1]*(delta[b1][c0]*delta[d0][d1] + delta[b1][d0]*delta[c0][d1] + delta[b1][d1]*delta[c0][d0]))

                    )

                    + F9_t[3] * 0.5 * S2 * S2 * inv_S1 * inv_S1 * inv_S4 * inv_S4 * inv_S4 * a_i * a_l * (

                        +(QC_0*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1] + QD_y*delta[d0][d1]) + QD_0*(QD_1*delta[c0][g1] + QD_y*delta[c0][d1]) + QD_1*QD_y*delta[c0][d0])*(PQ[a0]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + PQ[a1]*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1]) + PQ[b0]*(delta[a0][a1]*delta[b1][g0] + delta[a0][b1]*delta[a1][g0] + delta[a0][g0]*delta[a1][b1]) + PQ[b1]*(delta[a0][a1]*delta[b0][g0] + delta[a0][b0]*delta[a1][g0] + delta[a0][g0]*delta[a1][b0]) + PQ[g0]*(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0]))

                        +QC_0*QD_0*(QD_1*(delta[a0][a1]*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + delta[a0][b0]*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + delta[a0][b1]*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]) + delta[a0][g0]*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) + delta[a0][g1]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1])) + QD_y*(delta[a0][a1]*(delta[b0][b1]*delta[d1][g0] + delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1]) + delta[a0][b0]*(delta[a1][b1]*delta[d1][g0] + delta[a1][d1]*delta[b1][g0] + delta[a1][g0]*delta[b1][d1]) + delta[a0][b1]*(delta[a1][b0]*delta[d1][g0] + delta[a1][d1]*delta[b0][g0] + delta[a1][g0]*delta[b0][d1]) + delta[a0][d1]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + delta[a0][g0]*(delta[a1][b0]*delta[b1][d1] + delta[a1][b1]*delta[b0][d1] + delta[a1][d1]*delta[b0][b1]))) + QD_1*QD_y*(QC_0*(delta[a0][a1]*(delta[b0][b1]*delta[d0][g0] + delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0]) + delta[a0][b0]*(delta[a1][b1]*delta[d0][g0] + delta[a1][d0]*delta[b1][g0] + delta[a1][g0]*delta[b1][d0]) + delta[a0][b1]*(delta[a1][b0]*delta[d0][g0] + delta[a1][d0]*delta[b0][g0] + delta[a1][g0]*delta[b0][d0]) + delta[a0][d0]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + delta[a0][g0]*(delta[a1][b0]*delta[b1][d0] + delta[a1][b1]*delta[b0][d0] + delta[a1][d0]*delta[b0][b1])) + QD_0*(delta[a0][a1]*(delta[b0][b1]*delta[c0][g0] + delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0]) + delta[a0][b0]*(delta[a1][b1]*delta[c0][g0] + delta[a1][c0]*delta[b1][g0] + delta[a1][g0]*delta[b1][c0]) + delta[a0][b1]*(delta[a1][b0]*delta[c0][g0] + delta[a1][c0]*delta[b0][g0] + delta[a1][g0]*delta[b0][c0]) + delta[a0][c0]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + delta[a0][g0]*(delta[a1][b0]*delta[b1][c0] + delta[a1][b1]*delta[b0][c0] + delta[a1][c0]*delta[b0][b1])))

                    )

                    + F9_t[3] * (-0.25) * S2 * S2 * inv_S1 * inv_S1 * inv_S4 * inv_S4 * inv_S4 * a_i * (

                        +(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1])*(PQ[a0]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + PQ[a1]*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1]) + PQ[b0]*(delta[a0][a1]*delta[b1][g0] + delta[a0][b1]*delta[a1][g0] + delta[a0][g0]*delta[a1][b1]) + PQ[b1]*(delta[a0][a1]*delta[b0][g0] + delta[a0][b0]*delta[a1][g0] + delta[a0][g0]*delta[a1][b0]) + PQ[g0]*(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0]))

                        +QC_0*(delta[d0][g1]*(delta[a0][a1]*(delta[b0][b1]*delta[d1][g0] + delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1]) + delta[a0][b0]*(delta[a1][b1]*delta[d1][g0] + delta[a1][d1]*delta[b1][g0] + delta[a1][g0]*delta[b1][d1]) + delta[a0][b1]*(delta[a1][b0]*delta[d1][g0] + delta[a1][d1]*delta[b0][g0] + delta[a1][g0]*delta[b0][d1]) + delta[a0][d1]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + delta[a0][g0]*(delta[a1][b0]*delta[b1][d1] + delta[a1][b1]*delta[b0][d1] + delta[a1][d1]*delta[b0][b1])) + delta[d1][g1]*(delta[a0][a1]*(delta[b0][b1]*delta[d0][g0] + delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0]) + delta[a0][b0]*(delta[a1][b1]*delta[d0][g0] + delta[a1][d0]*delta[b1][g0] + delta[a1][g0]*delta[b1][d0]) + delta[a0][b1]*(delta[a1][b0]*delta[d0][g0] + delta[a1][d0]*delta[b0][g0] + delta[a1][g0]*delta[b0][d0]) + delta[a0][d0]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + delta[a0][g0]*(delta[a1][b0]*delta[b1][d0] + delta[a1][b1]*delta[b0][d0] + delta[a1][d0]*delta[b0][b1])))

                        +(QD_0*delta[d1][g1] + QD_1*delta[d0][g1])*(delta[a0][a1]*(delta[b0][b1]*delta[c0][g0] + delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0]) + delta[a0][b0]*(delta[a1][b1]*delta[c0][g0] + delta[a1][c0]*delta[b1][g0] + delta[a1][g0]*delta[b1][c0]) + delta[a0][b1]*(delta[a1][b0]*delta[c0][g0] + delta[a1][c0]*delta[b0][g0] + delta[a1][g0]*delta[b0][c0]) + delta[a0][c0]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + delta[a0][g0]*(delta[a1][b0]*delta[b1][c0] + delta[a1][b1]*delta[b0][c0] + delta[a1][c0]*delta[b0][b1]))

