                        +(QC_0*QD_y*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + QD_0*QD_1*(PQ[c0]*QD_y + PQ[g1]*QC_0))*(PA_0*(PA_1*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) + PQ[a1]*(PA_x*delta[b0][b1] + PB_0*delta[b1][g0] + PB_1*delta[b0][g0] - PQ[b0]*delta[b1][g0] - PQ[b1]*delta[b0][g0] - PQ[g0]*delta[b0][b1]) + delta[a1][g0]*(PB_0*PQ[b1] + PB_1*PQ[b0])) + PA_1*PQ[a0]*(PA_x*delta[b0][b1] + PB_0*delta[b1][g0] + PB_1*delta[b0][g0]) + PA_x*(PB_0*(PQ[a0]*delta[a1][b1] + PQ[a1]*delta[a0][b1]) + PB_1*(PQ[a0]*delta[a1][b0] + PQ[a1]*delta[a0][b0]) + PQ[b0]*(PA_0*delta[a1][b1] + PB_1*delta[a0][a1] + delta[a0][b1]*(PA_1 - PQ[a1])) + PQ[b1]*(PA_0*delta[a1][b0] + PB_0*delta[a0][a1] + delta[a0][b0]*(PA_1 - PQ[a1]))) + PB_0*(PB_1*(PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0]) + PQ[g0]*(PA_0*delta[a1][b1] + PB_1*delta[a0][a1] + delta[a0][b1]*(PA_1 - PQ[a1]))) + PB_1*PQ[g0]*(PA_0*delta[a1][b0] + delta[a0][b0]*(PA_1 - PQ[a1])) - PQ[a0]*(PA_1*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) + PA_x*(PQ[a1]*delta[b0][b1] + PQ[b0]*delta[a1][b1] + PQ[b1]*delta[a1][b0]) + PB_0*(PQ[a1]*delta[b1][g0] + PQ[b1]*delta[a1][g0] + PQ[g0]*delta[a1][b1]) + PB_1*(PQ[a1]*delta[b0][g0] + PQ[b0]*delta[a1][g0] + PQ[g0]*delta[a1][b0])) - PQ[b0]*(PQ[b1]*(PA_0*delta[a1][g0] + PA_1*delta[a0][g0] + PA_x*delta[a0][a1]) + PQ[g0]*(PA_0*delta[a1][b1] + PA_1*delta[a0][b1] + PB_1*delta[a0][a1])) - PQ[b1]*PQ[g0]*(PA_0*delta[a1][b0] + PA_1*delta[a0][b0] + PB_0*delta[a0][a1]) + delta[a0][g0]*(PA_1 - PQ[a1])*(PB_0*PQ[b1] + PB_1*PQ[b0]))

