                        +delta[b0][b1]*(PQ[a0]*delta[a1][g0] + PQ[a1]*delta[a0][g0])*(PQ[c0]*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1]) + QC_0*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1]))

