1] - PB_1*PQ[a1]*PQ[g0])*(delta[a0][c0]*delta[b0][d0]*delta[d1][g1] + delta[a0][c0]*delta[b0][d1]*delta[d0][g1] + delta[a0][d0]*delta[b0][c0]*delta[d1][g1] + delta[a0][d1]*delta[b0][c0]*delta[d0][g1]) + (-PA_x*PQ[b0]*PQ[b1] - PB_0*PQ[b1]*PQ[g0] - PB_1*PQ[b0]*PQ[g0])*(delta[a0][c0]*delta[a1][d0]*delta[d1][g1] + delta[a0][c0]*delta[a1][d1]*delta[d0][g1] + delta[a0][d0]*delta[a1][c0]*delta[d1][g1] + delta[a0][d1]*delta[a1][c0]*delta[d0][g1])

