                        +(PQ[a0]*PQ[g0]*(PB_0*PQ[a1]*PQ[b1] + PQ[b0]*(PA_1*PQ[b1] + PB_1*PQ[a1])) + PQ[a1]*PQ[b0]*PQ[b1]*(PA_0*PQ[g0] + PA_x*PQ[a0]))*(PQ[c0]*(delta[d0][d1]*(PQ[g1] + QD_y) + delta[d0][g1]*(PQ[d1] + QD_1) + delta[d1][g1]*(PQ[d0] + QD_0)) + PQ[d0]*(QC_0*delta[d1][g1] + delta[c0][d1]*(PQ[g1] + QD_y) + delta[c0][g1]*(PQ[d1] + QD_1)) + PQ[d1]*(QC_0*delta[d0][g1] + QD_0*delta[c0][g1] + delta[c0][d0]*(PQ[g1] + QD_y)) + PQ[g1]*(QC_0*delta[d0][d1] + QD_0*delta[c0][d1] + QD_1*delta[c0][d0]))

