                        +(PA_0*PA_1*QC_0 - PA_0*PQ[a1]*QC_0 - PA_1*PQ[a0]*QC_0)*(delta[b0][b1]*delta[d0][g0]*delta[d1][g1] + delta[b0][b1]*delta[d0][g1]*delta[d1][g0] + delta[b0][d0]*delta[b1][g0]*delta[d1][g1] + delta[b0][d1]*delta[b1][g0]*delta[d0][g1] + delta[b0][g0]*delta[b1][d0]*delta[d1][g1] + delta[b0][g0]*delta[b1][d1]*delta[d0][g1]) + (PA_0*PB_0*QC_0 - PA_0*PQ[b0]*QC_0 - PB_0*PQ[a0]*QC_0)*(delta[a1][b1]*delta[d0][g0]*delta[d1][g1] + delta[a1][b1]*delta[d0][g1]*delta[d1][g0] + delta[a1][d0]*delta[b1][g0]*delta[d1][g1] + delta[a1][d1]*delta[b1][g0]*delta[d0][g1] + delta[a1][g0]*delta[b1][d0]*delta[d1][g1] + delta[a1][g0]*delta[b1][d1]*delta[d0][g1]) + (PA_0*PB_1*QC_0 - PA_0*PQ[b1]*QC_0 - PB_1*PQ[a0]*QC_0)*(delta[a1][b0]*delta[d0][g0]*delta[d1][g1] + delta[a1][b0]*delta[d0][g1]*delta[d1][g0] + delta[a1][d0]*delta[b0][g0]*delta[d1][g1] + delta[a1][d1]*delta[b0][g0]*delta[d0][g1] + delta[a1][g0]*delta[b0][d0]*delta[d1][g1] + delta[a1][g0]*delta[b0][d1]*delta[d0][g1]) + (PA_0*PB_x*QC_0 - PA_0*PQ[g0]*QC_0 - PB_x*PQ[a0]*QC_0)*(delta[a1][b0]*delta[b1][d0]*delta[d1][g1] + delta[a1][b0]*delta[b1][d1]*delta[d0][g1] + delta[a1][b1]*delta[b0][d0]*delta[d1][g1] + delta[a1][b1]*delta[b0][d1]*delta[d0][g1] + delta[a1][d0]*delta[b0][b1]*delta[d1][g1] + delta[a1][d1]*delta[b0][b1]*delta[d0][g1]) + (PA_1*PB_0*QC_0 - PA_1*PQ[b0]*QC_0 - PB_0*PQ[a1]*QC_0)*(delta[a0][b1]*delta[d0][g0]*delta[d1][g1] + delta[a0][b1]*delta[d0][g1]*delta[d1][g0] + delta[a0][d0]*delta[b1][g0]*delta[d1][g1] + delta[a0][d1]*delta[b1][g0]*delta[d0][g1] + delta[a0][g0]*delta[b1][d0]*delta[d1][g1] + delta[a0][g0]*delta[b1][d1]*delta[d0][g1]) + (PA_1*PB_1*QC_0 - PA_1*PQ[b1]*QC_0 - PB_1*PQ[a1]*QC_0)*(delta[a0][b0]*delta[d0][g0]*delta[d1][g1] + delta[a0][b0]*delta[d0][g1]*delta[d1][g0] + delta[a0][d0]*delta[b0][g0]*delta[d1][g1] + delta[a0][d1]*delta[b0][g0]*delta[d0][g1] + delta[a0][g0]*delta[b0][d0]*delta[d1][g1] + delta[a0][g0]*delta[b0][d1]*delta[d0][g1]) + (PA_1*PB_x*QC_0 - PA_1*PQ[g0]*QC_0 - PB_x*PQ[a1]*QC_0)*(delta[a0][b0]*delta[b1][d0]*delta[d1][g1] + delta[a0][b0]*delta[b1][d1]*delta[d0][g1] + delta[a0][b1]*delta[b0][d0]*delta[d1][g1] + delta[a0][b1]*delta[b0][d1]*delta[d0][g1] + delta[a0][d0]*delta[b0][b1]*delta[d1][g1] + delta[a0][d1]*delta[b0][b1]*delta[d0][g1]) + (PB_0*PB_1*QC_0 - PB_0*PQ[b1]*QC_0 - PB_1*PQ[b0]*QC_0)*(delta[a0][a1]*delta[d0][g0]*delta[d1][g1] + delta[a0][a1]*delta[d0][g1]*delta[d1][g0] + delta[a0][d0]*delta[a1][g0]*delta[d1][g1] + delta[a0][d1]*delta[a1][g0]*delta[d0][g1] + delta[a0][g0]*delta[a1][d0]*delta[d1][g1] + delta[a0][g0]*delta[a1][d1]*delta[d0][g1]) + (PB_0*PB_x*QC_0 - PB_0*PQ[g0]*QC_0 - PB_x*PQ[b0]*QC_0)*(delta[a0][a1]*delta[b1][d0]*delta[d1][g1] + delta[a0][a1]*delta[b1][d1]*delta[d0][g1] + delta[a0][b1]*delta[a1][d0]*delta[d1][g1] + delta[a0][b1]*delta[a1][d1]*delta[d0][g1] + delta[a0][d0]*delta[a1][b1]*delta[d1][g1] + delta[a0][d1]*delta[a1][b1]*delta[d0][g1]) + (PB_1*PB_x*QC_0 - PB_1*PQ[g0]*QC_0 - PB_x*PQ[b1]*QC_0)*(delta[a0][a1]*delta[b0][d0]*delta[d1][g1] + delta[a0][a1]*delta[b0][d1]*delta[d0][g1] + delta[a0][b0]*delta[a1][d0]*delta[d1][g1] + delta[a0][b0]*delta[a1][d1]*delta[d0][g1] + delta[a0][d0]*delta[a1][b0]*delta[d1][g1] + delta[a0][d1]*delta[a1][b0]*delta[d0][g1])

                        +(PQ[c0]*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1]) + QC_0*(PQ[d0]*delta[d1][g1] + PQ[d1]*delta[d0][g1]))*(-2*PA_0*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) - 2*PA_1*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1]) - 2*PB_0*(delta[a0][a1]*delta[b1][g0] + delta[a0][b1]*delta[a1][g0] + delta[a0][g0]*delta[a1][b1]) - 2*PB_1*(delta[a0][a1]*delta[b0][g0] + delta[a0][b0]*delta[a1][g0] + delta[a0][g0]*delta[a1][b0]) - 2*PB_x*(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0]) + PQ[a0]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + PQ[a1]*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1]) + PQ[b0]*(delta[a0][a1]*delta[b1][g0] + delta[a0][b1]*delta[a1][g0] + delta[a0][g0]*delta[a1][b1]) + PQ[b1]*(delta[a0][a1]*delta[b0][g0] + delta[a0][b0]*delta[a1][g0] + delta[a0][g0]*delta[a1][b0]) + PQ[g0]*(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0]))

                    )

                    + F9_t[2] * 0.5 * S2 * inv_S1 * inv_S4 * inv_S4 * a_l * (

                        +(PQ[a0]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0]) + PQ[a1]*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0]))*(QC_0*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1] + QD_y*delta[d0][d1]) + QD_0*(QD_1*delta[c0][g1] + QD_y*delta[c0][d1]) + QD_1*QD_y*delta[c0][d0])

                        +delta[a0][a1]*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0])*(QC_0*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1] + QD_y*delta[d0][d1]) + QD_0*(QD_1*delta[c0][g1] + QD_y*delta[c0][d1]) + QD_1*QD_y*delta[c0][d0])

                        +QC_0*QD_0*(QD_1*(delta[b0][g0]*(delta[a0][a1]*delta[b1][g1] + delta[a0][b1]*delta[a1][g1] + delta[a0][g1]*delta[a1][b1]) + delta[b1][g0]*(delta[a0][a1]*delta[b0][g1] + delta[a0][b0]*delta[a1][g1] + delta[a0][g1]*delta[a1][b0])) + QD_y*(delta[b0][g0]*(delta[a0][a1]*delta[b1][d1] + delta[a0][b1]*delta[a1][d1] + delta[a0][d1]*delta[a1][b1]) + delta[b1][g0]*(delta[a0][a1]*delta[b0][d1] + delta[a0][b0]*delta[a1][d1] + delta[a0][d1]*delta[a1][b0]))) + QD_1*QD_y*(QC_0*(delta[b0][g0]*(delta[a0][a1]*delta[b1][d0] + delta[a0][b1]*delta[a1][d0] + delta[a0][d0]*delta[a1][b1]) + delta[b1][g0]*(delta[a0][a1]*delta[b0][d0] + delta[a0][b0]*delta[a1][d0] + delta[a0][d0]*delta[a1][b0])) + QD_0*(delta[b0][g0]*(delta[a0][a1]*delta[b1][c0] + delta[a0][b1]*delta[a1][c0] + delta[a0][c0]*delta[a1][b1]) + delta[b1][g0]*(delta[a0][a1]*delta[b0][c0] + delta[a0][b0]*delta[a1][c0] + delta[a0][c0]*delta[a1][b0])))

                    )

                    + F9_t[2] * (-0.25) * S2 * inv_S1 * inv_S4 * inv_S4 * (

                        +(PQ[a0]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0]) + PQ[a1]*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0]))*(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1])

                        +delta[a0][a1]*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0])*(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1])

                        +QC_0*(delta[b0][g0]*(delta[d0][g1]*(delta[a0][a1]*delta[b1][d1] + delta[a0][b1]*delta[a1][d1] + delta[a0][d1]*delta[a1][b1]) + delta[d1][g1]*(delta[a0][a1]*delta[b1][d0] + delta[a0][b1]*delta[a1][d0] + delta[a0][d0]*delta[a1][b1])) + delta[b1][g0]*(delta[d0][g1]*(delta[a0][a1]*delta[b0][d1] + delta[a0][b0]*delta[a1][d1] + delta[a0][d1]*delta[a1][b0]) + delta[d1][g1]*(delta[a0][a1]*delta[b0][d0] + delta[a0][b0]*delta[a1][d0] + delta[a0][d0]*delta[a1][b0])))

                        +(QD_0*delta[d1][g1] + QD_1*delta[d0][g1])*(delta[b0][g0]*(delta[a0][a1]*delta[b1][c0] + delta[a0][b1]*delta[a1][c0] + delta[a0][c0]*delta[a1][b1]) + delta[b1][g0]*(delta[a0][a1]*delta[b0][c0] + delta[a0][b0]*delta[a1][c0] + delta[a0][c0]*delta[a1][b0]))

                    )


                );

        ERIs[threadIdx.y] += eri_ijkl * pd_mat_D[kl] * kl_factor;
    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < dd_prim_pair_count_local))
    {
        double hess_jl_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM_LARGE; n++)
        {
            hess_jl_xy += ERIs[n];
        }

        atomicAdd(
            hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + j] * natoms + atom_idx_l,
            hess_jl_xy * ij_factor_D * 2.0 * prefac_coulomb);
    }

    __syncthreads();

    }
}

__global__ void __launch_bounds__(TILE_SIZE_J)
computeCoulombHessianDDPD_JL_12(double*         hess_xy,
                               double*         hess_yx,
                               const uint32_t  hess_cart_ind_0,
                               const uint32_t  hess_cart_ind_1,
                               const double    prefac_coulomb,
                               const double*   p_prim_info,
                               const uint32_t  p_prim_count,
                               const double*   d_prim_info,
                               const uint32_t  d_prim_count,
                               const double*   dd_mat_D_local,
                               const double*   pd_mat_D,
                               const double*   dd_mat_Q_local,
                               const double*   pd_mat_Q,
                               const uint32_t* dd_first_inds_local,
                               const uint32_t* dd_second_inds_local,
                               const double*   dd_pair_data_local,
                               const uint32_t  dd_prim_pair_count_local,
                               const uint32_t* pd_first_inds,
                               const uint32_t* pd_second_inds,
                               const double*   pd_pair_data,
                               const uint32_t  pd_prim_pair_count,
                               const uint32_t* prim_cart_ao_to_atom_inds,
                               const uint32_t  natoms,
                               const uint32_t* d_kl_inds_for_atom_l,
                               const uint32_t* d_kl_counts_for_atom_l,
                               const uint32_t* d_kl_displs_for_atom_l,
                               const uint32_t  s_prim_count,
                               const double*   boys_func_table,
                               const double*   boys_func_ft,
                               const double    eri_threshold)
{
    // each thread row scans over [ij|??] and sum up to a primitive J matrix element
    // J. Chem. Theory Comput. 2009, 5, 4, 1004-1015

    __shared__ double   ERIs[TILE_DIM_LARGE + 1];
    __shared__ uint32_t d_cart_inds[6][2];
    __shared__ double   delta[3][3];
    __shared__ uint32_t g0, g1;

    __shared__ double a_i, a_j, r_i[3], r_j[3], S_ij_00, S1, inv_S1, ij_factor_D;
    __shared__ double PA_0, PA_1, PB_0, PB_1, PB_x;
    __shared__ uint32_t i, j, a0, a1, b0, b1;

    ERIs[threadIdx.y] = 0.0;

    const uint32_t ij = blockDim.x * blockIdx.x + threadIdx.x;

    if ((threadIdx.y == 0) && (threadIdx.x == 0))
    {
        d_cart_inds[0][0] = 0; d_cart_inds[0][1] = 0;
        d_cart_inds[1][0] = 0; d_cart_inds[1][1] = 1;
        d_cart_inds[2][0] = 0; d_cart_inds[2][1] = 2;
        d_cart_inds[3][0] = 1; d_cart_inds[3][1] = 1;
        d_cart_inds[4][0] = 1; d_cart_inds[4][1] = 2;
        d_cart_inds[5][0] = 2; d_cart_inds[5][1] = 2;

        delta[0][0] = 1.0; delta[0][1] = 0.0; delta[0][2] = 0.0;
        delta[1][0] = 0.0; delta[1][1] = 1.0; delta[1][2] = 0.0;
        delta[2][0] = 0.0; delta[2][1] = 0.0; delta[2][2] = 1.0;

        g0 = hess_cart_ind_0;
