        double F9_t[4];

        gpu::computeBoysFunction(F9_t, S1 * S2 * inv_S4 * r2_PQ, 3, boys_func_table, boys_func_ft);

        const auto QC_0 = (a_l * inv_S2) * (r_l[c0] - r_k[c0]);
        const auto QD_0 = (-a_k * inv_S2) * (r_l[d0] - r_k[d0]);
        const auto QD_1 = (-a_k * inv_S2) * (r_l[d1] - r_k[d1]);

        const auto QD_y = (-a_k * inv_S2) * (r_l[g1] - r_k[g1]);

        double kl_factor = 2.0;

        // nu-sigma hessian

        const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                    + F9_t[3] * (-1.0) * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * a_l * (

                        +PQ[a0]*PQ[a1]*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0])*(QC_0*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1] + QD_y*delta[d0][d1]) + QD_0*(QD_1*delta[c0][g1] + QD_y*delta[c0][d1]) + QD_1*QD_y*delta[c0][d0])

                        +PQ[a0]*PQ[a1]*(QC_0*QD_0*(QD_1*(delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + QD_y*(delta[b0][d1]*delta[b1][g0] + delta[b0][g0]*delta[b1][d1])) + QD_1*QD_y*(QC_0*(delta[b0][d0]*delta[b1][g0] + delta[b0][g0]*delta[b1][d0]) + QD_0*(delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0])))

                        +(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0])*(QC_0*QD_0*(PQ[a0]*(QD_1*delta[a1][g1] + QD_y*delta[a1][d1]) + PQ[a1]*(QD_1*delta[a0][g1] + QD_y*delta[a0][d1])) + QD_1*QD_y*(PQ[a0]*(QC_0*delta[a1][d0] + QD_0*delta[a1][c0]) + PQ[a1]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0])))

                        +(PQ[a0]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0]) + PQ[a1]*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0]))*(QC_0*QD_y*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + QD_0*QD_1*(PQ[c0]*QD_y + PQ[g1]*QC_0))

                        +delta[a0][a1]*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0])*(QC_0*QD_y*(PQ[d0]*QD_1 + PQ[d1]*QD_0) + QD_0*QD_1*(PQ[c0]*QD_y + PQ[g1]*QC_0))

                    )


                );

        ERIs[threadIdx.y] += eri_ijkl * pd_mat_D[kl] * kl_factor;
    }

    __syncthreads();

    if ((threadIdx.y == 0) && (ij < dd_prim_pair_count_local))
    {
        double hess_jl_xy = 0.0;

        for (uint32_t n = 0; n < TILE_DIM_LARGE; n++)
        {
            hess_jl_xy += ERIs[n];
        }

        atomicAdd(
            hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + j] * natoms + atom_idx_l,
            hess_jl_xy * ij_factor_D * 2.0 * prefac_coulomb);
    }

    __syncthreads();

    }
}

