                        +PQ[c0]*(PQ[a0]*PQ[a1]*(PB_0*(PQ[b1]*(delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + PQ[g0]*(delta[b1][d0]*delta[d1][g1] + delta[b1][d1]*delta[d0][g1])) + PB_1*(PQ[b0]*(delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + PQ[g0]*(delta[b0][d0]*delta[d1][g1] + delta[b0][d1]*delta[d0][g1])) + PB_x*(PQ[b0]*(delta[b1][d0]*delta[d1][g1] + delta[b1][d1]*delta[d0][g1]) + PQ[b1]*(delta[b0][d0]*delta[d1][g1] + delta[b0][d1]*delta[d0][g1]))) + PQ[b0]*((PA_0*PQ[a1] + PA_1*PQ[a0])*(PQ[b1]*(delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + PQ[g0]*(delta[b1][d0]*delta[d1][g1] + delta[b1][d1]*delta[d0][g1])) + (PB_1*PQ[g0] + PB_x*PQ[b1])*(PQ[a0]*(delta[a1][d0]*delta[d1][g1] + delta[a1][d1]*delta[d0][g1]) + PQ[a1]*(delta[a0][d0]*delta[d1][g1] + delta[a0][d1]*delta[d0][g1]))) + PQ[b1]*PQ[g0]*(PA_0*(PQ[a1]*(delta[b0][d0]*delta[d1][g1] + delta[b0][d1]*delta[d0][g1]) + PQ[b0]*(delta[a1][d0]*delta[d1][g1] + delta[a1][d1]*delta[d0][g1])) + PA_1*(PQ[a0]*(delta[b0][d0]*delta[d1][g1] + delta[b0][d1]*delta[d0][g1]) + PQ[b0]*(delta[a0][d0]*delta[d1][g1] + delta[a0][d1]*delta[d0][g1])) + PB_0*(PQ[a0]*(delta[a1][d0]*delta[d1][g1] + delta[a1][d1]*delta[d0][g1]) + PQ[a1]*(delta[a0][d0]*delta[d1][g1] + delta[a0][d1]*delta[d0][g1]))))

